SELECT distinct a.project_id, cp.name AS projectName, cp.short_name AS projectShortName, cp.serial_number AS projectSerialNumber, a.monomer_id, monomer.name AS monomerName, a.area_id, area.name AS areaName, task_order.order_number FROM mes_building_task_process a LEFT JOIN contract_project cp ON cp.id = a.project_id LEFT JOIN plan_monomer monomer ON monomer.id = a.monomer_id LEFT JOIN plan_area area ON area.id = a.area_id LEFT JOIN mes_building_task_order task_order ON task_order.id=a.task_order_id LEFT JOIN ( SELECT task_process_id processId, IFNULL( sum( quantity ), 0 ) quantity, IFNULL( sum( produce_quantity ), 0 ) produceQuantity FROM mes_building_assist WHERE bool_delete_enum = 0 GROUP BY task_process_id ) assist ON a.id = assist.processId
LEFT JOIN mes_building_process process ON a.process_id=process.id
where a.bool_delete_enum = 0 AND cp.settlement_status=0 AND cp.status=1 and a.team_id in
#{teamId}
AND a.task_type_enum&#{taskTypeEnum}
and process.type!=${@com.hzchum.scim.mes.building.core.api.enums.process.ProcessTypeEnum@DRILL_HOLE.getType()}
AND a.bool_delete_enum=FALSE AND ( a.need_quantity - a.complete_quantity - IFNULL(( assist.quantity - assist.produceQuantity ), 0 ) ) > 0
AND ( a.project_id IN ( #{pId} )
or a.project_id=0
)
AND a.monomer_id = #{monomerId}
AND a.area_id = #{areaId}

SELECT
mba.steel_spec,
count(mba.steel_spec ) quantity
FROM
mes_building_task_process a
LEFT JOIN mes_building_production_line_team_link mbpltl on mbpltl.bool_delete_enum=FALSE and
a.production_line_id=mbpltl.production_line_id
LEFT JOIN mes_building_team mbt ON a.process_id=mbt.process_id AND mbpltl.team_id=mbt.id and
mbt.bool_delete_enum=FALSE
LEFT JOIN tech_machine_part mba ON a.product_id = mba.id

    mbt.id in
    
        #{team.id}
    
    AND a.product_type = ${@com.hzchum.scim.mes.building.core.api.enums.task.TaskTypeEnum@MACHINE_PART.getType()}
    AND a.bool_delete_enum=FALSE
    AND a.need_quantity>a.complete_quantity
    
        AND a.project_id = #{projectId}
    
    
        AND a.monomer_id = #{monomerId}
    
    
        AND a.area_id = #{areaId}
    
    
        and a.task_id=#{taskId}
    
    
        AND a.process_id = #{processId}
    
    
        AND mba.serial_Number like concat('%',#{serialNumber},'%')
    
    
        AND mba.name like concat('%',#{productName},'%')
    
    
    AND a.project_id IN
    (
    #{projectId}
)

GROUP BY mba.steel_spec ;

