    LEFT JOIN tech_assemble mba ON a.product_id =mba.id AND mba.bool_delete_enum=FALSE


    LEFT JOIN tech_machine_part mba ON a.product_id =mba.id AND mba.bool_delete_enum=FALSE


    mbt.id in
    
        #{team}
    
    AND a.product_type=#{productType}
    AND a.bool_delete_enum=FALSE
    AND a.need_quantity>a.complete_quantity
    
        AND a.project_id = #{projectId}
    
    
        AND a.monomer_id = #{monomerId}
    
    
        AND a.area_id = #{areaId}
    
    
        AND a.process_id = #{processId}
    
    AND a.project_id IN
    (
    #{team}
)

SELECT COUNT(*)
FROM mes_building_task_process a

    LEFT JOIN tech_artifact mba ON a.product_id =mba.id AND mba.bool_delete_enum=FALSE


    LEFT JOIN tech_enclosure mba ON a.product_id =mba.id AND mba.bool_delete_enum=FALSE


    LEFT JOIN tech_assemble mba ON a.product_id =mba.id AND mba.bool_delete_enum=FALSE


    LEFT JOIN tech_machine_part mba ON a.product_id =mba.id AND mba.bool_delete_enum=FALSE


    
        (
        a.process_id = #{assist.processId} AND a.task_id = #{assist.taskId}
    )
    
    AND a.product_type=#{productType}
    AND a.bool_delete_enum=FALSE
    AND a.need_quantity>a.complete_quantity
    
        AND a.project_id = #{projectId}
    
    
        AND a.monomer_id = #{monomerId}
    
    
        AND a.area_id = #{areaId}
    
    
        AND a.process_id = #{processId}
    
    

ORDER BY a.ask_complete_time

