select p.id 'project.id', p.name 'project.name', p.short_name 'project.short_name', p.serial_number 'project.serial_number', temp.quantity, temp.mete from contract_project p inner join( select tp.project_id, sum(tp.task_quantity) quantity,
sum(a.net_weight * tp.task_quantity) mete from mes_building_task_process tp inner join tech_artifact a on a.id = tp.product_id and tp.product_type = ${@com.hzchum.scim.mes.building.core.api.enums.ProductTypeEnum@ARTIFACT.getType()}
sum(a.length * tp.task_quantity) mete from mes_building_task_process tp inner join tech_enclosure a on a.id = tp.product_id and tp.product_type = ${@com.hzchum.scim.mes.building.core.api.enums.ProductTypeEnum@ENCLOSURE.getType()}
where tp.bool_delete_enum = 0 and tp.process_id = #{processId} and tp.production_line_id = #{productionLineId}
and date_format(tp.ask_complete_time, '%Y') = #{year}
and date_format(tp.ask_complete_time, '%Y-%m') = #{month}
group by tp.project_id) temp on temp.project_id = p.id where p.bool_delete_enum = 0

select
date_format(tp.ask_complete_time, '%c') date,
date_format(tp.ask_complete_time, '%e') date,
sum(tp.task_quantity) task_quantity, sum(tp.inspection_quantity) complete_quantity,
sum(a.net_weight * tp.task_quantity) task_mete, sum(a.net_weight * tp.inspection_quantity) complete_mete from mes_building_task_process tp inner join tech_artifact a on a.id = tp.product_id and tp.product_type = ${@com.hzchum.scim.mes.building.core.api.enums.ProductTypeEnum@ARTIFACT.getType()}
sum(a.length * tp.task_quantity) task_mete, sum(a.length * tp.inspection_quantity) complete_mete from mes_building_task_process tp inner join tech_enclosure a on a.id = tp.product_id and tp.product_type = ${@com.hzchum.scim.mes.building.core.api.enums.ProductTypeEnum@ENCLOSURE.getType()}
where tp.bool_delete_enum = 0 and tp.process_id = #{processId} and tp.production_line_id = #{productionLineId}
and date_format(tp.ask_complete_time, '%Y') = #{year}
and date_format(tp.ask_complete_time, '%Y-%m') = #{month}
group by date

select p.id 'project.id', p.name 'project.name', p.short_name 'project.short_name', p.serial_number 'project.serial_number', a.name, a.serial_number, a.net_weight, tp.task_quantity, tp.inspection_quantity complete_quantity, tp.complete_time from tech_artifact a inner join contract_project p on p.id = a.project_id inner join mes_building_task_process tp on tp.product_id = a.id and tp.product_type = ${@com.hzchum.scim.mes.building.core.api.enums.ProductTypeEnum@ARTIFACT.getType()}
and tp.bool_delete_enum = 0
and tp.project_id = #{projectId}
and tp.production_line_id = #{productionLineId}
and tp.process_id = #{processId}
and (p.name like CONCAT('%',#{name},'%') or p.short_name like CONCAT('%',#{name},'%'))
and a.serial_number like CONCAT('%',#{serialNumber},'%')
and date_format(tp.ask_complete_time, '%Y-%m') = #{month}
and date_format(tp.ask_complete_time, '%Y') = #{year}

