and (p.name like CONCAT('%',#{name},'%') or p.short_name like CONCAT('%',#{name},'%'))
and a.serial_number like CONCAT('%',#{serialNumber},'%')
and date_format(tp.ask_complete_time, '%Y-%m') = #{month}
and date_format(tp.ask_complete_time, '%Y') = #{year}

