SELECT a.id, a.scheduling_id scheduling_id, a.quantity, a.net_weight, a.order_number, a.device_type cut_type, a.ask_complete_time, a.project_id 'project.id', a.name 'project.name', a.serial_number 'project.serialNumber', a.user_name, a.create_time scheduling_date, a.short_name 'project.shortName' FROM ( SELECT task_order.scheduling_id scheduling_id, a.task_order_id id, a.quantity, partcutconfig.device_type, a.net_weight, task_order.order_number, u.name user_name, cp.id project_id, cp.`name`, cp.short_name, task_order.create_time, cp.serial_number, task_order.ask_complete_time FROM ( SELECT a.task_order_id, ANY_VALUE(a.project_id) AS project_id, sum((a.task_quantity - a.complete_quantity)) quantity, sum((a.task_quantity - a.complete_quantity) * mba.net_weight) net_weight FROM mes_building_task_process a LEFT JOIN mes_building_team team on team.id = a.team_id AND team.process_id = a.process_id AND team.bool_delete_enum = 0 LEFT JOIN tech_machine_part mba ON a.product_id = mba.id -- LEFT JOIN ( -- SELECT link.groups_id, -- link.team_id, -- team.process_id -- FROM mes_building_groups_team_link link -- LEFT JOIN mes_building_team team ON link.team_id = team.id -- WHERE link.bool_delete_enum = 0 -- ) mbt ON mbt.groups_id = a.groups_id -- AND mbt.process_id = a.process_id -- LEFT JOIN tech_machine_part mba ON a.product_id = mba.id WHERE a.process_id IN (SELECT id FROM `mes_building_process` WHERE type = 8 AND bool_delete_enum = FALSE) AND a.team_id in
#{groupsId}
AND(a.project_id in
#{pId}
or a.project_id=0
)
AND a.monomer_id = #{monomerId}
AND a.area_id = #{areaId}
AND a.task_type_enum = 1 AND a.bool_delete_enum = FALSE -- AND a.need_quantity > a.complete_quantity GROUP BY a.task_order_id ) a LEFT JOIN mes_building_task_order task_order ON task_order.id = a.task_order_id LEFT JOIN sys_user u ON task_order.user_id=u.id AND u.bool_delete_enum=0 LEFT JOIN mes_building_machine_part_team_detail partcutconfig ON task_order.cut_config_id = partcutconfig.id LEFT JOIN contract_project cp ON cp.id = a.project_id LEFT JOIN mes_building_machine_part_scheduling partscheduling ON task_order.scheduling_id = partscheduling.id
AND task_order.order_number like concat('%',#{orderNumber},'%')
ORDER BY task_order.ask_complete_time ) a WHERE a.id IS NOT NULL order by a.create_time desc -- AND a.quantity > 0

