SELECT p.id 'project.id', p.name 'project.name', p.serial_number 'project.serial_number', p.short_name 'project.short_name', pm.id 'monomer.id', pm.`name`'monomer.name', pa.id 'area.id', pa.`name` 'area.name', ta.serial_number serialNumber, ta.specification specification, ta.length length, ta.net_weight, ta.gross_weight, ta.net_weight * a.task_quantity total_net_weight, ta.gross_weight * a.task_quantity total_gross_weight, ta.surface_area / 1000000 AS surface_area, ta.surface_area * a.task_quantity / 1000000 AS total_surface_area, ta.remark, ta.name artifactName, ta.material as material, a.task_quantity quantity, a.in_production_quantity in_production_quantity, a.product_id product_id, a.task_type_enum taskType, a.ask_complete_time completeTime, a.taskId taskId FROM (
SELECT process.task_id taskId, process.project_id, process.monomer_id, process.area_id, process.product_id, sum(process.task_quantity) task_quantity, 0 in_production_quantity, process.task_type_enum, process.ask_complete_time FROM mes_building_task_process process INNER JOIN tech_artifact artifact on artifact.id = process.product_id and artifact.bool_delete_enum = 0
and artifact.serial_number = #{serialNumber}
and artifact.serial_number like CONCAT('%',#{serialNumber},'%')
and artifact.specification = #{specification}
and artifact.specification like CONCAT('%',#{specification},'%')
WHERE process.bool_delete_enum = 0 AND process.task_type_enum = 2
AND process.task_order_id = #{orderId}
AND process.process_id =#{processId}
AND process.project_id = #{projectId}
and ask_complete_time >= #{startDate}
and ask_complete_time <= #{endDate}
GROUP BY process.task_id, process.project_id, process.monomer_id, process.area_id, process.product_id, process.ask_complete_time
SELECT task.id taskId, task.project_id, task.monomer_id, task.area_id, task.product_id, sum(task.task_quantity) task_quantity, sum(task.in_production_quantity) in_production_quantity, task.task_type_enum, task.ask_complete_time FROM mes_building_task task INNER JOIN tech_artifact artifact on artifact.id = task.product_id and artifact.bool_delete_enum = 0
and artifact.serial_number = #{serialNumber}
and artifact.serial_number like CONCAT('%',#{serialNumber},'%')
and artifact.specification = #{specification}
and artifact.specification like CONCAT('%',#{specification},'%')
WHERE task.bool_delete_enum = 0 AND task.task_type_enum = 2
