and ask_complete_time >= #{startDate}
and ask_complete_time <= #{endDate}
GROUP BY task.id, task.project_id, task.monomer_id, task.area_id, task.product_id, task.ask_complete_time
) a LEFT JOIN contract_project p ON p.id = a.project_id LEFT JOIN plan_monomer pm ON pm.id = a.monomer_id LEFT JOIN plan_area pa ON pa.id = a.area_id LEFT JOIN tech_artifact ta ON ta.id = a.product_id

SELECT p.id 'project.id', p.name 'project.name', p.serial_number 'project.serial_number', p.short_name 'project.short_name', pm.id 'monomer.id', pm.`name`'monomer.name', pa.id 'area.id', pa.`name` 'area.name', ta.serial_number serialNumber, ta.specification specification, ta.length length, ta.net_weight netWeight, ta.gross_weight grossWeight, ta.net_weight * a.task_quantity total_net_weight, ta.gross_weight * a.task_quantity total_gross_weight, ta.surface_area / 1000000 AS surface_area, ta.surface_area * a.task_quantity / 1000000 AS total_surface_area, ta.remark, ta.name artifactName, a.task_quantity quantity, a.task_type_enum taskType, a.ask_complete_time completeTime FROM ( SELECT project_id, monomer_id, area_id, product_id, sum(task_quantity) task_quantity, task_type_enum, ask_complete_time FROM mes_building_task WHERE bool_delete_enum = 0 AND task_type_enum = 2
AND task_order_id = #{orderId}
AND project_id = #{projectId}
GROUP BY project_id, monomer_id, area_id, product_id, ask_complete_time ) a LEFT JOIN contract_project p ON p.id = a.project_id LEFT JOIN plan_monomer pm ON pm.id = a.monomer_id LEFT JOIN plan_area pa ON pa.id = a.area_id LEFT JOIN tech_artifact ta ON ta.id = a.product_id

SELECT p.id 'project.id', p.NAME 'project.name', p.serial_number 'project.serial_number', p.short_name 'project.short_name', ta.serial_number serialNumber, ta.specification specification, ta.length, ta.net_weight net_weight, ta.net_weight gross_weight, ta.net_weight * a.task_quantity total_net_weight, ta.net_weight * a.task_quantity total_gross_weight, ta.material as material, a.task_quantity quantity, a.task_type_enum taskType, a.task_id taskId, a.ask_complete_time completeTime FROM ( SELECT process.product_id, sum( process.task_quantity ) task_quantity, process.task_type_enum, process.task_id, process.ask_complete_time FROM mes_building_task_process process INNER JOIN tech_assemble assemble on assemble.id = process.product_id and assemble.bool_delete_enum = 0
