GROUP BY ta.id, a.task_type_enum, a.task_id, a.ask_complete_time ) a LEFT JOIN plan_monomer pm ON pm.id = a.monomer_id AND pm.bool_delete_enum =FALSE LEFT JOIN plan_area pa ON pa.id = a.area_id AND pa.bool_delete_enum =FALSE LEFT JOIN contract_project cp ON cp.id = a.project_id

SELECT cp.id 'project.id', cp.`name` 'project.name', cp.serial_number 'project.serialNumber', cp.short_name 'project.shortName', pm.id 'monomer.id', pm.`name` 'monomer.name', pa.id 'area.id', pa.`name` 'area.name', gr.`name` groupName , a.serialNumber serialNumber, a.specification specification, a.net_weight netWeight, a.gross_weight grossWeight, a.un_quantity unQuantity, a.net_weight*a.un_quantity un_net_weight, a.gross_weight*a.un_quantity un_gross_weight, a.ask_complete_time completeDate FROM ( SELECT a.task_type_enum, a.ask_complete_time, a.groups_id, CASE a.sequence WHEN 0 THEN sum( a.task_quantity - a.inspection_quantity ) ELSE sum( a.need_quantity - a.inspection_quantity ) END un_quantity,
ta.serial_number serialNumber, ta.specification specification, ta.net_weight net_weight, ta.gross_weight gross_weight, ta.project_id project_id, ta.monomer_id monomer_id, ta.area_id area_id
CASE a.task_type_enum WHEN 16 THEN ta.serial_number END serialNumber, CASE a.task_type_enum WHEN 16 THEN ta.specification END specification, CASE a.task_type_enum WHEN 16 THEN ta.net_weight END net_weight, CASE a.task_type_enum WHEN 16 THEN ta.net_weight END gross_weight, CASE a.task_type_enum WHEN 16 THEN ta.project_id END project_id, CASE a.task_type_enum WHEN 16 THEN ta.monomer_id END monomer_id, CASE a.task_type_enum WHEN 16 THEN ta.area_id ELSE 0 END area_id
FROM mes_building_task_process a
LEFT JOIN tech_artifact ta ON ta.id = a.product_id AND ta.bool_delete_enum = FALSE
LEFT JOIN tech_machine_part ta ON ta.id = a.product_id AND ta.bool_delete_enum = FALSE
LEFT JOIN tech_assemble ta ON ta.id = a.product_id
