AND (ta.serial_number like concat('%',#{serialNumber},'%')
GROUP BY a.task_type_enum, a.ask_complete_time, a.groups_id, ta.id, a.sequence ) a LEFT JOIN contract_project cp ON cp.id=a.project_id LEFT JOIN plan_monomer pm ON pm.id=a.monomer_id LEFT JOIN plan_area pa ON pa.id=a.area_id LEFT JOIN mes_building_groups gr ON gr.id=a.groups_id
