SELECT sum( quantity ) quantity, sum( quantity * net_weight ) mete FROM
tech_artifact
tech_machine_part
WHERE bool_delete_enum = 0
AND relation_type IN (2,16)
AND project_id = #{projectId}
AND monomer_id=#{monomerId}
AND area_id=#{areaId}

SELECT sum( a.quantity ) quantity, sum( a.mete ) mete FROM ( SELECT sum( quantity ) quantity, sum( quantity * net_weight ) mete FROM tech_assemble WHERE bool_delete_enum = 0
AND project_id = #{projectId}
AND monomer_id=#{monomerId}
AND area_id=#{areaId}
) a

SELECT a.id, a.name, a.product_type, SUM(a.task_quantity) quantity, SUM(a.total_net_weight) total_net_weight, SUM(a.total_gross_weight) total_gross_weight, SUM(a.complete_quantity) complete_quantity, SUM(a.complete_net_weight) complete_net_weight, SUM(a.complete_gross_weight) complete_gross_weight FROM ( SELECT b.id, b.`name`, b.sort, b.product_type, CASE b.product_type WHEN 1 THEN 1 WHEN 2 THEN 3 WHEN 16 THEN 2 END task_type_enum_sort, IFNULL( sum( a.task_quantity ), 0 ) task_quantity, IFNULL( sum( a.inspection_quantity ), 0 ) complete_quantity, CASE a.task_type_enum WHEN 2 THEN SUM( a.task_quantity * artifact.net_weight ) WHEN 16 THEN SUM( a.task_quantity * assemble.net_weight ) WHEN 1 THEN SUM( a.task_quantity * part.net_weight ) END total_net_weight, CASE a.task_type_enum WHEN 2 THEN SUM( a.task_quantity * artifact.gross_weight ) WHEN 16 THEN SUM( a.task_quantity * assemble.net_weight ) WHEN 1 THEN SUM( a.task_quantity * part.gross_weight ) END total_gross_weight, CASE a.task_type_enum WHEN 2 THEN SUM( a.inspection_quantity * artifact.net_weight ) WHEN 16 THEN SUM( a.inspection_quantity * assemble.net_weight ) WHEN 1 THEN SUM( a.inspection_quantity * part.net_weight ) END complete_net_weight, CASE a.task_type_enum WHEN 2 THEN SUM( a.inspection_quantity * artifact.gross_weight ) WHEN 16 THEN SUM( a.inspection_quantity * assemble.net_weight ) WHEN 1 THEN SUM( a.inspection_quantity * part.gross_weight ) END complete_gross_weight FROM mes_building_task_process a LEFT JOIN mes_building_process b ON b.id = a.process_id LEFT JOIN tech_artifact artifact ON artifact.id = a.product_id LEFT JOIN tech_machine_part part ON part.id = a.product_id LEFT JOIN tech_assemble assemble ON assemble.id = a.product_id WHERE a.bool_delete_enum = 0
AND a.project_id = #{projectId}
AND a.monomer_id=#{monomerId}
AND a.area_id=#{areaId}
AND a.production_line_id=#{productionLineId}
AND date(a.create_time) >= date(#{startDate})
AND date(a.create_time) <= date(#{endDate})
AND DATE_FORMAT( a.create_time, '%Y-%m' ) = DATE_FORMAT( #{dateTime}, '%Y-%m' )
AND a.workshop_id = #{workshopId}
GROUP BY b.id, a.task_type_enum ) a GROUP BY a.id, a.product_type ORDER BY a.task_type_enum_sort ASC,a.sort ASC

SELECT a.task_order_id, a.sequence, process.id 'process.id', process.`name` ' process.name', a.task_quantity 'totalTaskMete.quantity', a.task_net_weight 'totalTaskMete.netWeight', a.task_gross_weight 'totalTaskMete.grossWeight', a.complete_quantity 'totalCompleteMete.quantity', a.complete_net_weight 'totalCompleteMete.netWeight', a.complete_gross_weight 'totalCompleteMete.grossWeight' FROM (SELECT task_process.task_order_id, task_process.process_id, task_process.sequence, IFNULL( SUM( task_process.task_quantity ), 0 ) task_quantity, IFNULL( SUM( task_process.task_net_weight ), 0 ) task_net_weight, IFNULL( SUM( task_process.task_gross_weight ), 0 ) task_gross_weight, IFNULL( SUM( task_process.complete_quantity ), 0 ) complete_quantity, IFNULL( SUM( task_process.complete_net_weight ), 0 ) complete_net_weight, IFNULL( SUM( task_process.complete_gross_weight ), 0 ) complete_gross_weight FROM ( SELECT task_process.task_order_id, task_process.task_quantity, task_process.process_id, task_process.sequence, CASE task_process.task_type_enum WHEN 2 THEN task_process.task_quantity * artifact.net_weight WHEN 16 THEN task_process.task_quantity * assemble.net_weight END task_net_weight, CASE task_process.task_type_enum WHEN 2 THEN task_process.task_quantity * artifact.gross_weight WHEN 16 THEN task_process.task_quantity * assemble.net_weight END task_gross_weight, task_process.complete_quantity, CASE task_process.task_type_enum WHEN 2 THEN task_process.complete_quantity * artifact.net_weight WHEN 16 THEN task_process.complete_quantity * assemble.net_weight END complete_net_weight, CASE task_process.task_type_enum WHEN 2 THEN task_process.complete_quantity * artifact.gross_weight WHEN 16 THEN 0 ELSE 0 END complete_gross_weight FROM mes_building_task_process task_process LEFT JOIN tech_artifact artifact ON artifact.id = task_process.product_id LEFT JOIN tech_assemble assemble ON assemble.id = task_process.product_id WHERE task_process.task_type_enum & 18 AND task_process.bool_delete_enum=0 AND task_process.task_order_id IN
#{id}
) task_process GROUP BY task_process.task_order_id,task_process.process_id,task_process.sequence) a LEFT JOIN mes_building_process process ON a.process_id=process.id order by process.sort

SELECT pl.id 'productionLine.id', pl.NAME 'productionLine.name', pl.production_line_type_enum 'productionLine.productionLineTypeEnum', gr.id 'groups.id', gr.NAME 'groups.name', a.task_order_id 'order.id', a.order_number 'order.name', a.task_type_enum productType, cp.id 'project.id', cp.NAME 'project.name', cp.short_name 'project.shortName', cp.serial_number 'project.serialNumber', pm.id 'monomer.id', pm.`name` 'monomer.name', pa.id 'area.id', pa.`name` 'area.name', a.`name` NAME, a.serialNumber serialNumber, a.specification specification, a.net_weight, a.gross_weight, a.quantity quantity, a.completeQuantity completeQuantity FROM ( SELECT ta.`name`, ta.serial_number serialNumber, ta.specification specification, ta.net_weight net_weight, ta.gross_weight gross_weight, ta.project_id, ta.monomer_id, ta.area_id, IFNULL( sum( a.task_quantity ), 0 ) quantity, IFNULL( sum( a.complete_quantity ), 0 ) completeQuantity, a.task_type_enum, a.task_order_id, o.order_number, a.production_line_id, a.groups_id FROM mes_building_task a LEFT JOIN mes_building_task_order o ON o.id = a.task_order_id LEFT JOIN tech_artifact ta ON ta.id = a.product_id AND ta.bool_delete_enum = FALSE WHERE a.bool_delete_enum = FALSE AND a.task_type_enum = 2 AND a.task_order_id = #{taskOrderId}
AND a.project_id = #{projectId}
AND a.monomer_id = #{monomerId}
AND a.area_id = #{areaId}
AND a.production_line_id = #{productionLineId}
AND a.workshop_id = #{workshopId}
GROUP BY ta.id, a.groups_id, a.production_line_id ) a LEFT JOIN plan_monomer pm ON pm.id = a.monomer_id LEFT JOIN plan_area pa ON pa.id = a.area_id LEFT JOIN contract_project cp ON cp.id = a.project_id LEFT JOIN mes_building_production_line pl ON pl.id = a.production_line_id LEFT JOIN mes_building_groups gr ON gr.id = a.groups_id

SELECT a.id, a.need_quantity - a.complete_quantity quantity, a.STATUS, a.technology_status, a.task_type_enum, a.ask_complete_time, a.product_id, mba.serial_number, mba.specification, drawing.picture_path, mba.material, a.inspection_quantity 'receivedQuantity' FROM mes_building_task_process a LEFT JOIN tech_machine_part mba ON a.product_id = mba.id LEFT JOIN tech_drawing drawing ON mba.monomer_id=drawing.monomer_id AND drawing.serial_number=mba.serial_number AND drawing.bool_delete_enum=0 AND drawing.data_type=${@com.hzchum.scim.plan.core.api.enums.TechDataTypeEnum@NC_DRAWING.getType()} AND drawing.product_type is null WHERE a.process_id IN (SELECT id FROM `mes_building_process` WHERE type = 4 AND bool_delete_enum = FALSE) AND a.task_type_enum = 1 AND a.bool_delete_enum = FALSE
AND a.project_id=#{projectId}
AND a.monomer_id=#{monomerId}
AND a.area_id=#{areaId}
and mba.serial_number LIKE CONCAT('%', #{serialNumber},'%')
AND mba.bool_delete_enum = FALSE AND a.nest_cut_plate_id = #{nestCutPlateId} ORDER BY a.ask_complete_time, a.id

SELECT a.process_id id, a.task_type_enum, SUM( a.un_quantity ) un_quantity, SUM( a.un_net_weight ) un_net_weight, SUM( a.un_gross_weight ) un_gross_weight FROM ( SELECT a.process_id, SUM( a.un_quantity ) un_quantity, SUM( a.un_net_weight ) un_net_weight, SUM( a.un_gross_weight ) un_gross_weight, CASE a.task_type_enum WHEN 1 THEN a.task_type_enum WHEN 2 THEN a.task_type_enum ELSE 16 END task_type_enum FROM ( SELECT a.process_id, SUM( a.un_quantity ) un_quantity, a.task_type_enum, CASE a.task_type_enum WHEN 1 THEN IFNULL( SUM( a.un_quantity * part.net_weight ), 0 ) WHEN 2 THEN IFNULL( SUM( a.un_quantity * artifact.net_weight ), 0 ) WHEN 16 THEN IFNULL( SUM( a.un_quantity * assemble.net_weight ), 0 ) END un_net_weight, CASE a.task_type_enum WHEN 1 THEN IFNULL( SUM( a.un_quantity * part.gross_weight ), 0 ) WHEN 2 THEN IFNULL( SUM( a.un_quantity * artifact.gross_weight ), 0 ) WHEN 16 THEN IFNULL( SUM( a.un_quantity * assemble.net_weight ), 0 ) END un_gross_weight FROM ( SELECT process_id, product_id, task_type_enum, CASE sequence WHEN 0 THEN IFNULL( task_quantity - inspection_quantity, 0 ) ELSE IFNULL( need_quantity - inspection_quantity, 0 ) END un_quantity FROM mes_building_task_process WHERE bool_delete_enum = 0 AND project_id = #{projectId}
AND workshop_id = #{workshopId}
) a LEFT JOIN tech_artifact artifact ON artifact.id = a.product_id LEFT JOIN tech_machine_part part ON part.id = a.product_id LEFT JOIN tech_assemble assemble ON assemble.id = a.product_id GROUP BY a.process_id, a.task_type_enum ) a GROUP BY a.process_id, a.task_type_enum ) a GROUP BY a.process_id, a.task_type_enum

SELECT a.project_id, a.process_id id, a.task_type_enum, SUM( a.un_quantity ) un_quantity, SUM( a.un_net_weight ) un_net_weight, SUM( a.un_gross_weight ) un_gross_weight FROM ( SELECT a.project_id, a.process_id, SUM( a.un_quantity ) un_quantity, SUM( a.un_net_weight ) un_net_weight, SUM( a.un_gross_weight ) un_gross_weight, CASE a.task_type_enum WHEN 1 THEN a.task_type_enum WHEN 2 THEN a.task_type_enum ELSE 16 END task_type_enum FROM ( SELECT a.project_id, a.process_id, SUM( a.un_quantity ) un_quantity, a.task_type_enum, CASE a.task_type_enum WHEN 1 THEN IFNULL( SUM( a.un_quantity * part.net_weight ), 0 ) WHEN 2 THEN IFNULL( SUM( a.un_quantity * artifact.net_weight ), 0 ) WHEN 16 THEN IFNULL( SUM( a.un_quantity * assemble.net_weight ), 0 ) END un_net_weight, CASE a.task_type_enum WHEN 1 THEN IFNULL( SUM( a.un_quantity * part.gross_weight ), 0 ) WHEN 2 THEN IFNULL( SUM( a.un_quantity * artifact.gross_weight ), 0 ) WHEN 16 THEN IFNULL( SUM( a.un_quantity * assemble.net_weight ), 0 ) END un_gross_weight FROM ( SELECT process_id, product_id, task_type_enum, project_id, CASE sequence WHEN 0 THEN IFNULL( task_quantity - inspection_quantity, 0 ) ELSE IFNULL( need_quantity - inspection_quantity, 0 ) END un_quantity FROM mes_building_task_process WHERE bool_delete_enum = 0 and project_id in
#{projectId}
AND workshop_id = #{workshopId}
) a LEFT JOIN tech_artifact artifact ON artifact.id = a.product_id LEFT JOIN tech_machine_part part ON part.id = a.product_id LEFT JOIN tech_assemble assemble ON assemble.id = a.product_id GROUP BY a.process_id, a.task_type_enum, a.project_id ) a GROUP BY a.process_id, a.task_type_enum, a.project_id ) a GROUP BY a.process_id, a.task_type_enum, a.project_id

SELECT a.id, a.serial_number, a.specification, a.length, a.material, a.net_weight,
a.`name`, a.gross_weight, a.structure_class_id classId,
a.net_weight gross_weight, a.assemble_config_id classId,
a.quantity, t.task_quantity as task_quantity, t.produced_quantity as produced_quantity, t.completed_quantity as completed_quantity, CASE WHEN t.task_quantity > t.completed_quantity THEN 1 WHEN t.task_quantity = t.completed_quantity THEN 2 END state, ml.id as production_line_id, ml.`name` as production_name FROM
tech_artifact a
tech_assemble a
INNER JOIN ( SELECT product_id, SUM( task_quantity ) task_quantity, SUM( complete_quantity ) completed_quantity, SUM( in_production_quantity ) produced_quantity, production_line_id FROM mes_building_task WHERE bool_delete_enum = 0 AND task_type_enum = #{taskTypeEnum}
AND factory_id = #{factoryId}
AND production_line_id = #{productionLineId}
GROUP BY product_id,production_line_id ) t ON t.product_id = a.id left join mes_building_production_line ml on t.production_line_id =ml.id WHERE a.bool_delete_enum = 0
AND a.assemble_config_id = #{classificationId}
AND a.structure_class_id = #{classificationId}
AND a.area_id = #{areaId}
AND a.area_batch_id = #{areaBatchId}
AND a.serial_number like concat('%',#{serialNumber},'%')
AND a.specification like concat('%',#{specification},'%')
AND a.material like concat('%',#{material},'%')
ORDER BY state ASC

SELECT a.process_id, SUM( a.un_quantity ) un_quantity, SUM( a.un_net_weight ) un_net_weight, SUM( a.un_gross_weight ) un_gross_weight, a.task_type_enum FROM ( SELECT a.process_id, SUM( a.un_quantity ) un_quantity, a.task_type_enum, CASE a.task_type_enum WHEN 1 THEN IFNULL( SUM( a.un_quantity * part.net_weight ), 0 ) WHEN 16 THEN IFNULL( SUM( a.un_quantity * assemble.net_weight ), 0 ) END un_net_weight, CASE a.task_type_enum WHEN 1 THEN IFNULL( SUM( a.un_quantity * part.gross_weight ), 0 ) WHEN 16 THEN IFNULL( SUM( a.un_quantity * assemble.net_weight ), 0 ) END un_gross_weight FROM ( SELECT process_id, product_id, task_type_enum, CASE sequence WHEN 0 THEN IFNULL( task_quantity - inspection_quantity, 0 ) ELSE IFNULL( need_quantity - inspection_quantity, 0 ) END un_quantity FROM mes_building_task_process WHERE bool_delete_enum = 0 AND task_type_enum & 17
AND project_id =#{projectId}
and (
product_id in
#{assembleId}
or product_id in
#{machineId}
) ) a LEFT JOIN tech_machine_part part ON part.id = a.product_id LEFT JOIN tech_assemble assemble ON assemble.id = a.product_id GROUP BY a.process_id, a.task_type_enum ) a GROUP BY a.process_id, a.task_type_enum

SELECT DISTINCT line.product_type task_type_enum, process.production_line_id 'productionLine.id', line.`name` 'productionLine.name', process.groups_id 'groups.id', link.`name` 'groups.name', link.team_id 'team.id', link.user_id 'team.leaderId', link.user_name 'team.name' FROM mes_building_task_process process LEFT JOIN mes_building_production_line line ON line.id = process.production_line_id AND line.bool_delete_enum = 0 AND line.bool_enabled_enum = 1 INNER JOIN ( SELECT gr.id, gr.`name`, user_link.team_id, user_link.user_id, user_link.user_name FROM mes_building_groups gr INNER JOIN mes_building_groups_team_link group_link ON group_link.groups_id = gr.id AND group_link.bool_delete_enum = 0 INNER JOIN mes_building_team team ON team.id = group_link.team_id AND team.bool_delete_enum=0 INNER JOIN mes_building_team_user_link user_link ON team.id = user_link.team_id AND user_link.bool_delete_enum = 0 AND user_link.bool_leader_enum = 1 WHERE gr.bool_delete_enum = 0 AND team.process_id = #{processId} ) link ON link.id = process.groups_id WHERE process.bool_delete_enum = 0
AND process.workshop_id = #{workshopId}
AND process.process_id = #{processId}
AND process.task_type_enum = #{taskTypeEnum}
AND process.task_type_enum & 16

SELECT cp.id 'project.id', cp.`name` 'project.name', cp.short_name 'project.shortName', cp.serial_number 'project.contractNo', pm.id 'monomer.id', pm.`name` 'monomer.name', pa.id 'area.id', pa.`name` 'area.name', a.id, a.serial_number, a.material, a.specification, a.length, CASE WHEN a.schedule_quantity > a.complete_quantity THEN 1 WHEN a.schedule_quantity = a.complete_quantity THEN 2 END status, a.complete_quantity, a.schedule_quantity, a.complete_net_weight, a.complete_gross_weight, a.schedule_net_weight, a.schedule_gross_weight FROM ( SELECT a.project_id, a.monomer_id, a.area_id, IFNULL( SUM( a.task_quantity), 0 ) schedule_quantity, IFNULL( SUM(a.inspection_quantity), 0 ) complete_quantity,
CASE a.task_type_enum WHEN 16 THEN ta.id END id, CASE a.task_type_enum WHEN 16 THEN ta.serial_number END serial_number, CASE a.task_type_enum WHEN 16 THEN ta.specification END specification, CASE a.task_type_enum WHEN 16 THEN ta.material END material, CASE a.task_type_enum WHEN 16 THEN ta.length END length, CASE a.task_type_enum WHEN 16 THEN IFNULL( SUM( a.inspection_quantity * ta.net_weight ), 0 ) END complete_net_weight, CASE a.task_type_enum WHEN 16 THEN IFNULL( SUM(a.inspection_quantity * ta.net_weight ), 0 ) END complete_gross_weight, CASE a.task_type_enum WHEN 16 THEN IFNULL( SUM(a.task_quantity * ta.net_weight ), 0 ) END schedule_net_weight, CASE a.task_type_enum WHEN 16 THEN IFNULL( SUM(a.task_quantity * ta.net_weight ), 0 ) END schedule_gross_weight
ta.id, ta.serial_number, ta.specification, ta.material, ta.length, IFNULL( SUM( a.inspection_quantity * ta.net_weight ), 0 ) complete_net_weight, IFNULL( SUM( a.inspection_quantity * ta.gross_weight ), 0 ) complete_gross_weight, IFNULL( SUM(a.task_quantity * ta.net_weight ), 0 ) schedule_net_weight, IFNULL( SUM(a.task_quantity * ta.gross_weight ), 0 ) schedule_gross_weight
FROM mes_building_task_process a
LEFT JOIN tech_artifact ta ON ta.id = a.product_id
LEFT JOIN tech_assemble ta ON ta.id = a.product_id
LEFT JOIN tech_machine_part ta ON ta.id = a.product_id
WHERE a.bool_delete_enum = 0 and a.process_id = #{processId}
AND a.workshop_id = #{workshopId}
AND a.production_line_id = #{productionLineId}
AND a.groups_id = #{groupId}
AND a.project_id = #{projectId}
AND a.monomer_id = #{monomerId}
AND a.area_id = #{areaId}
AND a.task_type_enum & 16
AND (ta.serial_number like concat('%',#{serialNumber},'%'))
AND a.task_type_enum = #{taskTypeEnum}
AND ta.serial_number like concat('%',#{serialNumber},'%')
GROUP BY a.project_id, a.monomer_id, a.area_id, ta.id
,a.task_type_enum
) a LEFT JOIN contract_project cp ON cp.id = a.project_id LEFT JOIN plan_monomer pm ON pm.id = a.monomer_id LEFT JOIN plan_area pa ON pa.id = a.area_id WHERE a.schedule_quantity >0 ORDER BY status ASC,a.complete_quantity ASC

SELECT cp.id 'project.id', cp.NAME 'project.name', cp.short_name 'project.shortName', cp.serial_number 'project.serialNumber', pm.id 'monomer.id', pm.`name` 'monomer.name' , pa.id 'area.id', pa.`name` 'area.name',
a.name name,
a.serialNumber serialNumber, a.specification specification, a.net_weight netWeight, a.gross_weight grossWeight, a.quantity quantity, IFNULL(a.quantity*a.net_weight,0) total_net_weight, IFNULL(a.quantity*a.gross_weight,0) total_gross_weight, a.complete_quantity complete_quantity, IFNULL(a.complete_quantity*a.net_weight,0) complete_net_weight, IFNULL(a.complete_quantity*a.gross_weight,0) complete_gross_weight, a.completeDate completeDate FROM ( SELECT ta.`name` name, ta.serial_number serialNumber, ta.specification specification, ta.net_weight net_weight, ta.gross_weight gross_weight, ta.project_id, ta.monomer_id, ta.area_id, IFNULL(sum( a.task_quantity ),0) quantity, IFNULL(sum( a.complete_quantity ),0) complete_quantity, a.ask_complete_time completeDate FROM `mes_building_task` a LEFT JOIN tech_artifact ta ON ta.id = a.product_id AND ta.bool_delete_enum = FALSE where a.bool_delete_enum = FALSE
AND a.monomer_id =#{monomerId}
AND a.task_type_enum = #{taskType}
AND a.area_id =#{areaId}
AND a.task_order_id = #{orderId}
AND a.production_line_id = #{prodLineId}
AND a.project_id in
#{projectId}
AND a.product_id in
#{singleArtifactId}
AND ta.NAME like concat('%',#{name},'%')
AND ta.serial_number like concat('%',#{serialNumber},'%')
GROUP BY ta.id, a.task_type_enum, a.ask_complete_time ) a LEFT JOIN plan_monomer pm ON pm.id = a.monomer_id AND pm.bool_delete_enum =FALSE LEFT JOIN plan_area pa ON pa.id = a.area_id AND pa.bool_delete_enum =FALSE LEFT JOIN contract_project cp ON cp.id = a.project_id

SELECT a.task_type_enum product_type, IFNULL( sum( a.task_quantity ), 0 ) quantity, IFNULL( sum( a.complete_quantity ), 0 ) complete_quantity, SUM( a.task_quantity * artifact.net_weight ) total_net_weight, SUM( a.task_quantity * artifact.gross_weight ) total_gross_weight, SUM( a.complete_quantity * artifact.net_weight )complete_net_weight, SUM( a.complete_quantity * artifact.gross_weight ) complete_gross_weight FROM mes_building_task a LEFT JOIN tech_artifact artifact ON artifact.id = a.product_id WHERE a.bool_delete_enum = 0 and a.task_type_enum=2
AND a.project_id = #{projectId}
AND a.monomer_id=#{monomerId}
AND a.area_id=#{areaId}
AND a.production_line_id=#{productionLineId}
AND date(a.create_time) >= date(#{startDate})
AND date(a.create_time) <= date(#{endDate})
AND a.product_id in
#{singleArtifactId}
GROUP BY a.task_type_enum

SELECT a.id, a.bc_guid, a.job_id, a.quantity, a.completeQuantity, a.net_weight, a.order_number, a.cut_name, a.ask_complete_time, a.project_id 'project.id', a.name 'project.name', a.serial_number 'project.serialNumber', a.short_name 'project.shortName' FROM( SELECT a.task_order_id id, partscheduling.bc_guid, partscheduling.job_id, a.quantity, a.completeQuantity,
a.net_weight,
task_order.order_number, cut_config.name cut_name, task_order.ask_complete_time, cp.id project_id, cp.`name`, cp.short_name, cp.serial_number FROM( SELECT a.task_order_id, a.project_id, sum(a.task_quantity) quantity, sum(a.complete_quantity) completeQuantity,
sum(a.task_quantity*mba.net_weight) net_weight
sum(a.task_quantity*mba.weight) net_weight
FROM mes_building_task_process a LEFT JOIN mes_building_product_process pro on a.product_process_id = pro.id AND pro.bool_delete_enum=FALSE LEFT JOIN ( SELECT task_process_id processId, IFNULL( sum( quantity ), 0 ) quantity, IFNULL( sum( produce_quantity ), 0 ) produceQuantity FROM mes_building_assist WHERE bool_delete_enum = 0 GROUP BY task_process_id ) assist ON a.id = assist.processId LEFT JOIN mes_building_team team ON a.team_id = team.id and team.bool_delete_enum=FALSE
LEFT JOIN tech_artifact mba ON a.product_id =mba.id
LEFT JOIN tech_enclosure mba ON a.product_id =mba.id
LEFT JOIN tech_assemble mba ON a.product_id =mba.id
LEFT JOIN tech_machine_part mba ON a.product_id =mba.id
LEFT JOIN mes_building_process process ON a.process_id=process.id
a.team_id in
#{teamId}
AND a.task_type_enum&#{taskTypeEnum}
AND a.next_processid is null
and process.type!=${@com.hzchum.scim.mes.building.core.api.enums.process.ProcessTypeEnum@DRILL_HOLE.getType()}
AND mba.serial_number like concat('%',#{serialNumber},'%')
AND a.bool_delete_enum=FALSE AND ( a.need_quantity - a.complete_quantity - IFNULL(( assist.quantity - assist.produceQuantity ), 0 ) ) > 0
AND ( a.project_id IN ( #{projectId} )
or a.project_id=0
)
AND a.monomer_id = #{monomerId}
AND a.area_id = #{areaId}
AND a.area_batch_id = #{areaBatchId}
AND a.process_id = #{processId} and mbt.process_id = #{processId}
GROUP BY a.task_order_id,a.project_id
) a LEFT JOIN mes_building_task_order task_order ON task_order.id=a.task_order_id LEFT JOIN mes_building_cut_config cut_config ON task_order.cut_config_id=cut_config.id LEFT JOIN contract_project cp ON cp.id = a.project_id LEFT JOIN mes_building_machine_part_scheduling partscheduling ON task_order.scheduling_id = partscheduling.id WHERE task_order.bool_delete_enum=0 AND cp.settlement_status=0 AND cp.status=1
AND task_order.order_number like concat('%',#{orderNumber},'%')
ORDER BY task_order.ask_complete_time) a WHERE a.id IS NOT NULL

select task.classification_id,pro.team_id
from mes_building_task task
left join mes_building_task_process pro on task.id = pro.task_id and pro.bool_delete_enum = 0
where task.bool_delete_enum = 0
and pro.workshop_id = #{workshopId}
and pro.process_id = #{processId}
and pro.team_id in

    #{teamId}

and task.classification_id in

    #{classId}

and pro.complete_quantity > pro.inspection_quantity

SELECT a.id, COUNT(distinct detail.number) AS quantity, a.STATUS, a.technology_status, a.task_type_enum, a.ask_complete_time, a.product_id, a.sequence, a.project_id 'project.id', cp.`name` 'project.name', cp.short_name 'project.short_name', cp.serial_number 'project.serial_number', a.monomer_id 'monomer.id', pm.`name` 'monomer.name', a.area_id 'area.id', pd.`name` 'area.name', a.area_batch_id 'areaBatch.id', batch.`name` 'areaBatch.name', a.process_id 'process.id', mbp.name 'process.name', mba.specification, mba.length, mba.material, case a.sequence when 0 THEN 1 else 0 end bool_first_process, mbp.report_type report_type, ass.production_line_id 'assistProductionLine.id', ass.production_line_id 'assistGroup.id',
mba.serial_number, class.id class_id, class.classification_name class_name
mba.serial_number
FROM mes_building_assist ass LEFT JOIN mes_building_task_process a on ass.task_process_id = a.id and a.bool_delete_enum =0 LEFT JOIN mes_building_assist_number_detail detail on detail.task_process_id = a.id and detail.bool_delete_enum =0 and detail.bool_finish_enum =0 and detail.assist_id = ass.id
INNER JOIN mes_building_task_number_link link ON link.artifact_task_process_id = detail.task_process_id and link.bool_artifact_report = false and link.bool_delete_enum = 0 and link.artifact_number = detail.number
INNER JOIN mes_building_task_number_link link ON link.assemble_task_process_id = detail.task_process_id and link.bool_assemble_report = false and link.bool_delete_enum = 0 and link.assemble_number = detail.number
LEFT JOIN contract_project cp ON cp.id =a.project_id AND cp.bool_delete_enum=FALSE LEFT JOIN plan_monomer pm ON pm.id =a.monomer_id AND pm.bool_delete_enum=FALSE LEFT JOIN plan_area pd ON pd.id =a.area_id AND pd.bool_delete_enum=FALSE LEFT JOIN plan_area_batch batch ON batch.id =a.area_batch_id AND batch.bool_delete_enum=FALSE LEFT JOIN mes_building_process mbp on mbp.id=a.process_id AND mbp.bool_delete_enum=FALSE
LEFT JOIN tech_artifact mba ON a.product_id =mba.id LEFT JOIN sys_structure_classification class ON mba.structure_class_id=class.id
LEFT JOIN tech_assemble mba ON a.product_id =mba.id LEFT JOIN sys_assemble_config class ON mba.assemble_config_id=class.id
ass.bool_delete_enum = 0 and a.process_id in
#{processId}
AND a.next_processid is null
AND ass.production_line_id=#{assistProdLineId} AND a.task_type_enum & #{taskTypeEnum} AND a.bool_delete_enum = FALSE AND ass.quantity - ass.produce_quantity > 0
AND a.task_order_id = #{taskOrderId}
AND a.monomer_id = #{monomerId}
AND a.area_id = #{areaId}
AND a.area_batch_id = #{areaBatchId}
AND a.task_id= #{taskId}
AND mba.serial_number like concat('%',#{serialNumber},'%') or mba.name like concat('%',#{serialNumber},'%')
AND class.id= #{classId}
GROUP BY a.id, a.sequence, ass.production_line_id

SELECT pro.process_id id, pro.product_id productId, pro.task_type_enum taskTypeEnum, sum( pro.need_quantity ) needQuantity, sum( pro.inspection_quantity ) completeQuantity FROM mes_building_task_process pro left join tech_artifact ta on pro.product_id = ta.id and ta.bool_delete_enum = 0 WHERE pro.bool_delete_enum = 0
and pro.product_id in
#{artId}
and pro.task_type_enum = #{taskTypeEnum}
and pro.need_quantity > 0
and pro.monomer_id = #{monmerId}
and pro.area_id = #{areaId}
and ta.structure_class_id = #{classId}
and ta.serial_number like concat('%',#{serialNumber},'%')
and pro.area_id in
#{areaId}
GROUP BY pro.product_id, pro.process_id, pro.task_type_enum

SELECT ass.id, wk.id 'workshop.id', wk.`name` 'workshop.name', pm.id 'monomer.id', pm.`name` 'monomer.name', pa.id 'area.id', pa.`name` 'area.name', mba.`name` className, ass.serial_number, ass.specification, ass.length, ass.material, pro.process_id, pro.task_type_enum, count( tnlink.assemble_id ) needQuantity, IFNULL( sum( rep.quantity ), 0 ) completedQuantity FROM mes_building_task_number_link tnlink LEFT JOIN mes_building_task_process pro ON tnlink.assemble_task_process_id = pro.id LEFT JOIN tech_assemble ass ON pro.product_id = ass.id AND ass.bool_delete_enum = 0 LEFT JOIN sys_assemble_config mba ON ass.assemble_config_id =mba.id LEFT JOIN mes_building_team_user_link tulink ON pro.team_id = tulink.team_id AND tulink.bool_delete_enum = 0 AND tulink.bool_leader_enum = 1 LEFT JOIN plan_monomer pm ON pro.monomer_id = pm.id AND pm.bool_delete_enum = 0 LEFT JOIN plan_area pa ON pro.area_id = pa.id AND pa.bool_delete_enum = 0 LEFT JOIN mes_building_workshop wk ON pro.workshop_id = wk.id AND pa.bool_delete_enum = 0 LEFT JOIN mes_building_produce_team_report rep ON tnlink.assemble_task_id = rep.task_id AND tnlink.assemble_number = rep.number WHERE tnlink.bool_delete_enum = 0 AND pro.bool_delete_enum = 0 AND rep.bool_delete_enum = 0 AND pro.need_quantity > 0
and tnlink.artifact_id = #{productId}
and pro.process_id = #{processId}
and ass.assemble_config_id = #{classId}
and ass.serial_number = #{serial_number}
GROUP BY ass.id, wk.id, pm.id, pa.id, mba.`name`, pro.process_id, pro.task_type_enum

SELECT art.id, wk.id 'workshop.id', wk.`name` 'workshop.name', pm.id 'monomer.id', pm.`name` 'monomer.name', pa.id 'area.id', pa.`name` 'area.name', mba.classification_name className, art.serial_number, art.specification, art.length, art.material, pro.process_id, pro.task_type_enum, sum( pro.need_quantity ) needQuantity, IFNULL( sum( pro.complete_quantity ), 0 ) completedQuantity FROM tech_artifact art LEFT JOIN mes_building_task_process pro ON art.id = pro.product_id AND pro.bool_delete_enum = 0 LEFT JOIN sys_structure_classification mba ON art.structure_class_id = mba.id LEFT JOIN mes_building_team_user_link tulink ON pro.team_id = tulink.team_id AND tulink.bool_delete_enum = 0 AND tulink.bool_leader_enum = 1 LEFT JOIN plan_monomer pm ON pro.monomer_id = pm.id AND pm.bool_delete_enum = 0 LEFT JOIN plan_area pa ON pro.area_id = pa.id AND pa.bool_delete_enum = 0 LEFT JOIN mes_building_workshop wk ON pro.workshop_id = wk.id AND pa.bool_delete_enum = 0 WHERE art.bool_delete_enum = 0 AND pro.bool_delete_enum = 0 AND pro.need_quantity > 0
and art.id = #{productId}
and pro.process_id = #{processId}
and art.structure_class_id = #{classId}
and art.serial_number = #{serial_number}
GROUP BY art.id, wk.id, pm.id, pa.id, mba.`classification_name`, pro.process_id, pro.task_type_enum

select pro.*
from mes_building_task_process pro

    left join tech_artifact ta on pro.product_id = ta.id and ta.bool_delete_enum = 0


    left join tech_assemble ta on pro.product_id = ta.id and ta.bool_delete_enum = 0

where pro.bool_delete_enum = 0

    and ta.structure_class_id = #{dtoParam.typeId}


    and ta.assemble_config_id =#{dtoParam.typeId}

and pro.task_type_enum = #{dtoParam.productType}
and pro.production_line_id = #{dtoParam.lineId}
and pro.process_id in

    #{processId}

SELECT workshop.name AS workshopName, line.name AS productionLineName, monomer.name AS monomerName, area.name AS areaName, product.name, product.serial_number, product.specification, product.length, product.material, product.net_weight, product.net_weight * task.task_quantity AS totalNetWeight, product.gross_weight, product.gross_weight * task.task_quantity AS totalGrossWeight, task.task_quantity, task.complete_quantity, product.net_weight * task.complete_quantity AS totalCompleteNetWeight, product.gross_weight * task.complete_quantity AS totalCompleteGrossWeight, task.create_time, task.ask_complete_time from mes_building_task task
left join tech_artifact product on task.product_id = product.id and product.bool_delete_enum = 0
left join tech_assemble product on task.product_id = product.id and product.bool_delete_enum = 0
left join tech_machine_part product on task.product_id = product.id and product.bool_delete_enum = 0
LEFT JOIN plan_monomer monomer on monomer.id = task.monomer_id and monomer.bool_delete_enum =0 LEFT JOIN plan_area area on area.id = task.area_id and area.bool_delete_enum =0 LEFT JOIN mes_building_workshop workshop on workshop.id = task.workshop_id and workshop.bool_delete_enum =0 LEFT JOIN mes_building_production_line line on line.id = task.production_line_id and line.bool_delete_enum =0 where task.bool_delete_enum = 0 and task.project_id = #{dtoParam.projectId} and task.task_type_enum = #{dtoParam.productType}
and task.workshop_id = #{dtoParam.workShopId}
and task.production_line_id = #{dtoParam.productionLineId}
and task.monomer_id = #{dtoParam.monomerId}
AND task.area_id IN
#{areaId}
and product.serial_number = #{dtoParam.serialNumber}
and product.serial_number like CONCAT('%',#{dtoParam.serialNumber},'%')
and product.specification = #{dtoParam.specification}
and product.specification like CONCAT('%',#{dtoParam.specification},'%')
and task.task_quantity = task.complete_quantity
and task.task_quantity > task.complete_quantity
AND date_format(task.create_time, '%Y-%m-%d') >= date_format(#{dtoParam.dateTimeList[0]}, '%Y-%m-%d')
AND date_format(task.create_time, '%Y-%m-%d') <= date_format(#{dtoParam.dateTimeList[1]}, '%Y-%m-%d')
order by task.complete_quantity

SELECT workshop.name AS workshopName, line.name AS productionLineName, monomer.name AS monomerName, area.name AS areaName, product.name, product.serial_number, product.specification, product.length, product.material, product.net_weight, product.net_weight * taskProcess.task_quantity AS totalNetWeight, product.gross_weight, product.gross_weight * taskProcess.task_quantity AS totalGrossWeight, taskProcess.task_quantity, taskProcess.inspection_quantity AS complete_quantity, taskProcess.create_time, taskProcess.ask_complete_time, teamLink.user_name AS teamUserName, process.name AS processName, product.net_weight * taskProcess.inspection_quantity AS totalCompleteNetWeight, product.gross_weight * taskProcess.inspection_quantity AS totalCompleteGrossWeight from mes_building_task_process taskProcess
left join tech_artifact product on taskProcess.product_id = product.id and product.bool_delete_enum = 0
left join tech_assemble product on taskProcess.product_id = product.id and product.bool_delete_enum = 0
left join tech_machine_part product on taskProcess.product_id = product.id and product.bool_delete_enum = 0
LEFT JOIN plan_monomer monomer on monomer.id = taskProcess.monomer_id and monomer.bool_delete_enum =0 LEFT JOIN plan_area area on area.id = taskProcess.area_id and area.bool_delete_enum =0 LEFT JOIN mes_building_workshop workshop on workshop.id = taskProcess.workshop_id and workshop.bool_delete_enum =0 LEFT JOIN mes_building_production_line line on line.id = taskProcess.production_line_id and line.bool_delete_enum =0 LEFT JOIN mes_building_process process on process.id = taskProcess.process_id and process.bool_delete_enum =0 LEFT JOIN mes_building_team team on team.id = taskProcess.team_id and team.bool_delete_enum =0 LEFT JOIN mes_building_team_user_link teamLink on teamLink.team_id = team.id and teamLink.bool_delete_enum =0 and teamLink.bool_leader_enum = 1 where taskProcess.bool_delete_enum = 0 and taskProcess.project_id = #{dtoParam.projectId} and taskProcess.task_type_enum = #{dtoParam.productType}
and taskProcess.workshop_id = #{dtoParam.workShopId}
and taskProcess.process_id = #{dtoParam.processId}
and taskProcess.production_line_id = #{dtoParam.productionLineId}
and taskProcess.monomer_id = #{dtoParam.monomerId}
and taskProcess.team_id = #{dtoParam.teamId}
AND taskProcess.area_id IN
#{areaId}
and product.serial_number = #{dtoParam.serialNumber}
and product.serial_number like CONCAT('%',#{dtoParam.serialNumber},'%')
and product.specification = #{dtoParam.specification}
and product.specification like CONCAT('%',#{dtoParam.specification},'%')
and taskProcess.task_quantity = taskProcess.complete_quantity
and taskProcess.task_quantity > taskProcess.complete_quantity
AND date_format(taskProcess.create_time, '%Y-%m-%d') >= date_format(#{dtoParam.dateTimeList[0]}, '%Y-%m-%d')
AND date_format(taskProcess.create_time, '%Y-%m-%d') <= date_format(#{dtoParam.dateTimeList[1]}, '%Y-%m-%d')
order by taskProcess.complete_quantity

SELECT a.process_id 'process.id', b.`name` 'process.name', b.type 'process.type', a.production_line_id 'productionLine.id', line.`name` 'productionLine.name', a.team_id 'team.id', tulink.user_name 'team.name', a.project_id 'project.id', cp.name 'project.name', cp.serial_number 'project.serialNumber', cp.short_name 'project.shortName', a.workshop_id 'workshop.id', mbw.`name` 'workshop.name', SUM(a.un_quantity) unQuantity, SUM(a.need_quantity) quantity, SUM(a.inspection_quantity) completeQuantity, a.task_type_enum productType, CASE a.task_type_enum WHEN 2 THEN IFNULL( SUM( a.un_quantity * ta.net_weight ), 0 ) ELSE IFNULL ( SUM( a.un_quantity * tb.net_weight ), 0 ) END total_net_weight, CASE a.task_type_enum WHEN 2 THEN IFNULL( SUM( a.un_quantity * ta.gross_weight ), 0 ) ELSE IFNULL ( SUM( a.un_quantity * tb.gross_weight ), 0 ) END total_gross_weight FROM ( SELECT a.process_id, a.product_id, a.production_line_id, a.team_id, a.project_id, a.workshop_id, a.inspection_quantity, CASE a.sequence WHEN 0 THEN a.task_quantity ELSE a.need_quantity END need_quantity, CASE a.sequence WHEN 0 THEN a.task_quantity - a.inspection_quantity ELSE a.need_quantity - a.inspection_quantity END un_quantity, a.task_type_enum FROM mes_building_task_process a WHERE a.bool_delete_enum = 0 AND a.task_type_enum & 3 AND DATEDIFF( NOW(), a.ask_complete_time )> 0
AND a.workshop_id = #{workShopId}
AND a.production_line_id = #{productionLineId}
AND a.process_id = #{processId}
AND a.project_id = #{projectId}
AND a.team_id = #{teamId}
) a LEFT JOIN contract_project cp ON cp.id=a.project_id AND cp.bool_delete_enum=FALSE LEFT JOIN mes_building_workshop mbw ON mbw.id=a.workshop_id AND mbw.bool_delete_enum=FALSE LEFT JOIN mes_building_process b ON b.id = a.process_id LEFT JOIN mes_building_production_line line ON line.id = a.production_line_id LEFT JOIN tech_artifact ta ON ta.id = a.product_id LEFT JOIN tech_machine_part tb ON tb.id = a.product_id LEFT JOIN mes_building_team_user_link tulink ON tulink.team_id = a.team_id AND tulink.bool_leader_enum = 1 AND tulink.bool_delete_enum = 0 WHERE a.un_quantity > 0 GROUP BY a.workshop_id, a.production_line_id, a.process_id, a.task_type_enum, a.team_id, tulink.user_name, a.project_id

SELECT a.process_id 'process.id', a.process_name 'process.name', a.type 'process.type', a.production_line_id 'productionLine.id', a.line_name 'productionLine.name', a.team_id 'team.id', tulink.user_name 'team.name', a.project_id 'project.id', cp.name 'project.name', cp.serial_number 'project.serialNumber', cp.short_name 'project.shortName', a.workshop_id 'workshop.id', mbw.`name` 'workshop.name', SUM(a.un_quantity) unQuantity, SUM(a.need_quantity) quantity, SUM(a.inspection_quantity) completeQuantity, a.product_type productType, SUM(a.total_net_weight) total_net_weight, SUM(a.total_gross_weight) total_gross_weight FROM ( SELECT a.workshop_id, a.production_line_id, line.`name` line_name, a.process_id, b.`name` process_name, b.type, b.product_type, a.team_id, a.project_id, SUM(a.need_quantity) need_quantity, SUM(a.un_quantity ) un_quantity, SUM(a.inspection_quantity) inspection_quantity, CASE a.task_type_enum WHEN 16 THEN IFNULL( SUM( a.un_quantity * ta.net_weight ), 0 ) END total_net_weight, CASE a.task_type_enum WHEN 16 THEN IFNULL( SUM( a.un_quantity * ta.net_weight ), 0 ) END total_gross_weight FROM ( SELECT a.workshop_id, a.production_line_id, a.process_id, a.team_id, a.product_id, a.project_id, a.sequence, a.inspection_quantity, CASE a.sequence WHEN 0 THEN a.task_quantity ELSE a.need_quantity END need_quantity, CASE a.sequence WHEN 0 THEN a.task_quantity - a.inspection_quantity ELSE a.need_quantity - a.inspection_quantity END un_quantity, a.task_type_enum FROM mes_building_task_process a WHERE a.bool_delete_enum = 0 AND a.task_type_enum & 16 AND DATEDIFF( NOW(), a.ask_complete_time )> 0
AND a.workshop_id = #{workShopId}
AND a.production_line_id = #{productionLineId}
AND a.process_id = #{processId}
AND a.project_id = #{projectId}
AND a.team_id = #{teamId}
) a LEFT JOIN mes_building_process b ON b.id = a.process_id LEFT JOIN mes_building_production_line line ON line.id = a.production_line_id LEFT JOIN tech_assemble ta ON ta.id = a.product_id WHERE a.un_quantity > 0 GROUP BY a.workshop_id, a.production_line_id, a.process_id, a.task_type_enum, a.team_id, a.project_id, a.sequence ) a LEFT JOIN mes_building_team_user_link tulink ON tulink.team_id = a.team_id AND tulink.bool_leader_enum = 1 AND tulink.bool_delete_enum = 0 LEFT JOIN contract_project cp ON cp.id=a.project_id AND cp.bool_delete_enum=FALSE LEFT JOIN mes_building_workshop mbw ON mbw.id=a.workshop_id AND mbw.bool_delete_enum=FALSE GROUP BY a.workshop_id, a.production_line_id, a.process_id, a.team_id, tulink.user_name, a.project_id

SELECT cp.id 'project.id', cp.`name` 'project.name', cp.serial_number 'project.serialNumber', cp.short_name 'project.shortName', pm.id 'monomer.id', pm.`name` 'monomer.name', pa.id 'area.id', pa.`name` 'area.name', batch.id 'areaBatch.id', batch.`name` 'areaBatch.name', tul.`user_name` groupName , a.name name, a.length length, a.material material, a.serialNumber serialNumber, a.specification specification, a.net_weight netWeight, a.gross_weight grossWeight, a.un_quantity unQuantity, a.need_quantity quantity, a.inspection_quantity completeQuantity, a.net_weight*a.un_quantity un_net_weight, a.gross_weight*a.un_quantity un_gross_weight, a.ask_complete_time completeDate FROM ( SELECT a.team_id as team_id, a.task_type_enum, a.ask_complete_time, CASE WHEN sum(a.inspection_quantity) = 0 THEN 0 else 1 END completeQuantitySort, sum(a.inspection_quantity) inspection_quantity, CASE a.sequence WHEN 0 THEN sum( a.task_quantity ) ELSE sum(a.need_quantity) END need_quantity, CASE a.sequence WHEN 0 THEN sum( a.task_quantity - a.inspection_quantity ) ELSE sum( a.need_quantity - a.inspection_quantity ) END un_quantity, ta.name, ta.length, ta.material,
ta.serial_number serialNumber, ta.specification specification, ta.net_weight net_weight, ta.gross_weight gross_weight, ta.project_id project_id, ta.monomer_id monomer_id, ta.area_id area_id, ta.area_batch_id area_batch_id
CASE a.task_type_enum WHEN 16 THEN ta.serial_number END serialNumber, CASE a.task_type_enum WHEN 16 THEN ta.specification END specification, CASE a.task_type_enum WHEN 16 THEN ta.net_weight END net_weight, CASE a.task_type_enum WHEN 16 THEN ta.net_weight END gross_weight, CASE a.task_type_enum WHEN 16 THEN ta.project_id END project_id, CASE a.task_type_enum WHEN 16 THEN ta.monomer_id END monomer_id, CASE a.task_type_enum WHEN 16 THEN ta.area_id ELSE 0 END area_id, CASE a.task_type_enum WHEN 16 THEN ta.area_batch_id ELSE 0 END area_batch_id
FROM mes_building_task_process a
LEFT JOIN tech_artifact ta ON ta.id = a.product_id AND ta.bool_delete_enum = FALSE
LEFT JOIN tech_machine_part ta ON ta.id = a.product_id AND ta.bool_delete_enum = FALSE
LEFT JOIN tech_assemble ta ON ta.id = a.product_id
WHERE a.bool_delete_enum = FALSE AND ((a.sequence!=0 and a.need_quantity - a.inspection_quantity != 0) or (a.sequence=0 and a.task_quantity - a.inspection_quantity != 0))
AND a.project_id in
#{projectId}
AND a.team_id =#{groupId}
AND a.task_type_enum= #{taskType}
AND a.task_type_enum & 16
AND a.process_id = #{processId}
AND a.production_line_id = #{productionLineId}
AND ta.serial_number like concat('%',#{serialNumber},'%')
AND (ta.serial_number like concat('%',#{serialNumber},'%')
GROUP BY a.team_id, a.task_type_enum, ta.id, a.ask_complete_time, a.sequence ) a LEFT JOIN contract_project cp ON cp.id=a.project_id and cp.bool_delete_enum = 0 LEFT JOIN plan_monomer pm ON pm.id=a.monomer_id and pm.bool_delete_enum = 0 LEFT JOIN plan_area pa ON pa.id=a.area_id and pa.bool_delete_enum = 0 LEFT JOIN plan_area_batch batch ON batch.id =a.area_batch_id and batch.bool_delete_enum = 0 LEFT JOIN mes_building_team_user_link tul on tul.team_id = a.team_id and tul.bool_leader_enum = 1 and tul.bool_delete_enum = 0
AND cp.id in
#{projectId}
AND pm.id =#{monomerId}
AND pa.id =#{areaId}
AND a.team_id =#{groupId}
AND a.un_quantity>0 AND DATEDIFF( NOW(), a.ask_complete_time )> 0
order by completeQuantitySort asc,unQuantity desc

SELECT distinct part.serial_number, part.specification, taskProcess.task_id taskId, taskProcess.id AS taskProcessId, taskProcess.product_id partId, line.NAME AS productionLineName, teamLink.user_name AS teamUserName, process.NAME AS processName, taskOrder.order_number AS orderNumber, config.`name` configName, taskProcess.inspection_quantity AS companyQuantity , taskProcess.task_quantity As taskQuantity FROM mes_building_task_process taskProcess LEFT JOIN mes_building_team_user_link teamLink ON teamLink.team_id = taskProcess.team_id AND teamLink.bool_leader_enum = 1 and teamLink.bool_delete_enum =0 LEFT JOIN mes_building_process process ON process.id = taskProcess.process_id LEFT JOIN mes_building_production_line line ON line.id = taskProcess.production_line_id LEFT JOIN mes_building_task_order taskOrder on taskOrder.id = taskProcess.task_order_id LEFT JOIN mes_building_cut_config config ON config.id =taskOrder.cut_config_id AND config.bool_delete_enum=0 LEFT JOIN tech_machine_part part ON part.id = taskProcess.product_id and part.bool_delete_enum = 0 WHERE taskProcess.bool_delete_enum = 0 and taskProcess.task_type_enum = 1 and taskProcess.product_id in
#{item}
order by part.serial_number

SELECT workshop.id AS 'workShop.id', workshop.name AS 'workShop.name', line.id AS 'productionLine.id', line.name AS 'productionLine.name', monomer.id As 'monomer.id', monomer.name As 'monomer.name', area.id As 'area.id', area.name As 'area.name', process.name AS processName, product.product_classification_enum, product.serial_number, product.specification, product.length, product.material, product.net_weight, product.gross_weight, sum(taskProcess.task_quantity) AS task_quantity, sum(taskProcess.inspection_quantity) AS complete_quantity, sum(taskProcess.task_quantity - taskProcess.inspection_quantity) AS remainingQuantity FROM mes_building_task_process taskProcess LEFT JOIN tech_machine_part product on product.id = taskProcess.product_id LEFT JOIN mes_building_workshop workshop on workshop.id = taskProcess.workshop_id LEFT JOIN mes_building_production_line line on line.id = taskProcess.production_line_id LEFT JOIN mes_building_process process on process.id = taskProcess.process_id LEFT JOIN plan_monomer monomer on monomer.id = taskProcess.monomer_id LEFT JOIN plan_area area on area.id = taskProcess.area_id where taskProcess.bool_delete_enum =0 and taskProcess.project_id = #{projectId} and taskProcess.task_type_enum = #{productType}
and taskProcess.process_id = #{processId}
and product.product_classification_enum = #{productClassificationEnum}
AND product.serial_number like concat('%', #{serialNumber}, '%')
and taskProcess.workshop_id = #{workShopId}
and taskProcess.production_line_id = #{productionLineId}
and taskProcess.monomer_id = #{monomerId}
and taskProcess.area_id in
#{areaId}
and taskProcess.complete_quantity = 0
and (taskProcess.complete_quantity > 0 and taskProcess.complete_quantity < task.task_quantity)
and taskProcess.complete_quantity = taskProcess.task_quantity
and taskProcess.area_batch_id in
#{areaBatchId}
group by workshop.id, workshop.name , line.id , line.name , monomer.id , monomer.name , area.id , area.name , process.name , product.product_classification_enum, product.serial_number, product.specification, product.length, product.material, product.net_weight, product.gross_weight order by complete_quantity

SELECT a.DATE, IFNULL(a.oneQuantity,0) oneQuantity, IFNULL(b.twoQuantity,0) twoQuantity FROM ( SELECT DATE_FORMAT( tp.create_time, '%Y-%m' ) DATE, round( sum( task_quantity * art.net_weight ) / 1000, 2 ) oneQuantity FROM mes_building_task tp LEFT JOIN tech_artifact art ON tp.product_id = art.id AND art.bool_delete_enum = 0 WHERE tp.bool_delete_enum = 0 AND tp.task_type_enum = 2 AND DATE_FORMAT( tp.create_time, '%Y') = DATE_FORMAT( #{date}, '%Y')
AND tp.workshop_id = #{workShopId}
GROUP BY DATE_FORMAT( tp.create_time, '%Y-%m' ) ) a LEFT JOIN ( SELECT DATE_FORMAT( c.create_time, '%Y-%m' ) DATE, round( sum( c.quantity * art.net_weight ) / 1000, 2 ) twoQuantity FROM `mes_building_complete` c LEFT JOIN tech_artifact art ON c.product_id = art.id AND art.bool_delete_enum = 0 WHERE c.bool_delete_enum = 0 AND c.task_type_enum = 2 AND DATE_FORMAT( c.create_time, '%Y') = DATE_FORMAT( #{date}, '%Y')
AND c.workshop_id = #{workShopId}
GROUP BY DATE_FORMAT( c.create_time, '%Y-%m' )) b ON a.DATE = b.DATE

SELECT "构件" AS productTaskName, IFNULL( a.inspection_quantity * ta.net_weight, 0 ) AS inspectionQuantity, IFNULL( a.task_quantity * ta.net_weight, 0 ) AS quantity, p.NAME AS projectName FROM mes_building_task_process a LEFT JOIN tech_artifact ta ON ta.id = a.product_id LEFT JOIN contract_project p ON p.id = a.project_id WHERE ta.bool_delete_enum = FALSE AND p.bool_delete_enum = FALSE
AND YEAR(a.create_time) = #{year}
AND a.workshop_id = #{workshopId}
UNION ALL
SELECT "零件" AS productTaskName, IFNULL( a.inspection_quantity * ta.net_weight, 0 ) AS inspectionQuantity, IFNULL( a.task_quantity * ta.net_weight, 0 ) AS quantity, p.NAME AS projectName FROM mes_building_task_process a LEFT JOIN tech_machine_part ta ON ta.id = a.product_id LEFT JOIN contract_project p ON p.id = a.project_id WHERE ta.bool_delete_enum = FALSE AND p.bool_delete_enum = FALSE
AND YEAR(a.create_time) = #{year}
AND a.workshop_id = #{workshopId}
UNION ALL
SELECT "部件" AS productTaskName, IFNULL( a.inspection_quantity * ta.net_weight, 0 ) AS inspectionQuantity, IFNULL( a.task_quantity * ta.net_weight, 0 ) AS quantity, p.NAME AS projectName FROM mes_building_task_process a LEFT JOIN tech_assemble ta ON ta.id = a.product_id LEFT JOIN contract_project p ON p.id = a.project_id WHERE ta.bool_delete_enum = FALSE AND p.bool_delete_enum = FALSE
AND YEAR(a.create_time) = #{year}
AND a.workshop_id = #{workshopId}

SELECT report.todayInspectionQuantity, report.yesterdayInspectionQuantity, process.NAME AS processName, user_link.user_name AS teamName FROM ( SELECT SUM( CASE WHEN DATE(report.create_time) = CURDATE() THEN CASE WHEN report.task_type_enum = 1 THEN IFNULL(report.inspection_quantity * part.net_weight, 0) WHEN report.task_type_enum = 2 THEN IFNULL(report.inspection_quantity * artifact.net_weight, 0) WHEN report.task_type_enum = 16 THEN IFNULL(report.inspection_quantity * assemble.net_weight, 0) ELSE 0 END ELSE 0 END ) AS todayInspectionQuantity, SUM( CASE WHEN DATE(report.create_time) = CURDATE() - INTERVAL 1 DAY THEN CASE WHEN report.task_type_enum = 1 THEN IFNULL(report.inspection_quantity * part.net_weight, 0) WHEN report.task_type_enum = 2 THEN IFNULL(report.inspection_quantity * artifact.net_weight, 0) WHEN report.task_type_enum = 16 THEN IFNULL(report.inspection_quantity * assemble.net_weight, 0) ELSE 0 END ELSE 0 END ) AS yesterdayInspectionQuantity, report.process_id, report.team_id FROM mes_building_produce_team_report report LEFT JOIN mes_building_team team ON team.id = report.team_id LEFT JOIN tech_artifact artifact ON artifact.id = report.product_id LEFT JOIN tech_assemble assemble ON assemble.id = report.product_id LEFT JOIN tech_machine_part part ON part.id = report.product_id WHERE report.create_time >= CURDATE() - INTERVAL 1 DAY AND report.create_time < CURDATE() + INTERVAL 1 DAY AND report.bool_delete_enum = FALSE
AND team.workshop_id = #{workshopId}
GROUP BY report.team_id, report.process_id ) report LEFT JOIN mes_building_process process ON report.process_id = process.id LEFT JOIN mes_building_team_user_link user_link ON report.team_id = user_link.team_id WHERE process.bool_delete_enum = FALSE AND user_link.bool_delete_enum = FALSE;

SELECT user_link.user_name as teamName, SUM(CASE WHEN DATE(report.create_time) = CURDATE() - INTERVAL 1 DAY THEN CASE WHEN report.task_type_enum = 1 THEN IFNULL(report.inspection_quantity * part.net_weight, 0) WHEN report.task_type_enum = 2 THEN IFNULL(report.inspection_quantity * artifact.net_weight, 0) WHEN report.task_type_enum = 16 THEN IFNULL(report.inspection_quantity * assemble.net_weight, 0) ELSE 0 END ELSE 0 END) AS inspectionQuantity FROM mes_building_produce_team_report report LEFT JOIN mes_building_team team on report.team_id = team.id LEFT JOIN mes_building_team_user_link user_link ON user_link.team_id = team.id LEFT JOIN tech_artifact artifact ON artifact.id = report.product_id LEFT JOIN tech_assemble assemble ON assemble.id = report.product_id LEFT JOIN tech_machine_part part ON part.id = report.product_id WHERE report.bool_delete_enum = FALSE
AND YEAR(report.create_time) = #{year}
AND MONTH(report.create_time) = #{month}
AND team.workshop_id = #{workshopId}
GROUP BY user_link.user_name ORDER BY inspectionQuantity DESC LIMIT 3;

SELECT cp.serial_number 'project.serialNumber', cp.short_name 'project.shortName', shop.`id` 'workshop.id', shop.`name` 'workshop.name', pss.`name` 'processName', pro.monomer_id , pro.product_id, pro.production_line_id, pro.task_type_enum, pro.number, CASE pro.task_type_enum WHEN 2 THEN art.serial_number WHEN 16 THEN ass.serial_number END serial_number, CASE pro.task_type_enum WHEN 2 THEN art.artifact_type END artifact_type, CASE pro.task_type_enum WHEN 2 THEN art.structure_class_id WHEN 16 THEN ass.assemble_config_id END classificationId, CASE pro.task_type_enum WHEN 2 THEN art.specification WHEN 16 THEN ass.specification END specification, tulink.team_id 'team.id', tulink.user_name 'team.name', team.workshop_id 'team.workshopId', pro.create_time FROM mes_building_produce_team_report pro left join mes_building_task task on pro.task_id = task.id and task.bool_delete_enum = 0 left join contract_project cp on task.project_id = cp.id and cp.bool_delete_enum = 0 left join mes_building_workshop shop on task.workshop_id = shop.id and shop.bool_delete_enum = 0 left join mes_building_process pss on pro.process_id = pss.id and pss.bool_delete_enum = 0 left join tech_artifact art on pro.product_id = art.id and art.bool_delete_enum = 0 and pro.task_type_enum = 2 left join tech_assemble ass on pro.product_id = ass.id and ass.bool_delete_enum = 0 and pro.task_type_enum = 16 left join mes_building_team_user_link tulink on pro.team_id = tulink.team_id and tulink.bool_delete_enum = 0 and tulink.bool_leader_enum = 1 LEFT join mes_building_team team on pro.team_id = team.id and team.bool_delete_enum = 0
pro.bool_delete_enum = 0 and pro.quantity > pro.inspection_quantity
and
pro.team_id in
#{team.id}
and (art.structure_class_id in
#{classId}
or ass.assemble_config_id in
#{classId}
)
and pro.create_time >= #{startDate}
and pro.create_time <= #{endDate}
and task.project_id = #{projectId}
and shop.id = #{workShopId}
and art.serial_number like concat('%',#{serialNumber},'%') or ass.serial_number like concat('%',#{serialNumber},'%')

SELECT cp.serial_number 'project.serialNumber', cp.short_name 'project.shortName', shop.`id` 'workshop.id', shop.`name` 'workshop.name', pss.`name` 'processName', pro.monomer_id , pro.product_id, pro.production_line_id, pro.task_type_enum, pro.number, CASE pro.task_type_enum WHEN 2 THEN art.serial_number WHEN 16 THEN ass.serial_number END serial_number, CASE pro.task_type_enum WHEN 2 THEN art.artifact_type END artifact_type, CASE pro.task_type_enum WHEN 2 THEN art.structure_class_id WHEN 16 THEN ass.assemble_config_id END classificationId, CASE pro.task_type_enum WHEN 2 THEN art.specification WHEN 16 THEN ass.specification END specification, tulink.team_id 'team.id', tulink.user_name 'team.name', pro.create_time FROM mes_building_produce_team_report pro left join mes_building_task task on pro.task_id = task.id and task.bool_delete_enum = 0 left join contract_project cp on task.project_id = cp.id and cp.bool_delete_enum = 0 left join mes_building_workshop shop on task.workshop_id = shop.id and shop.bool_delete_enum = 0 left join mes_building_process pss on pro.process_id = pss.id and pss.bool_delete_enum = 0 left join tech_artifact art on pro.product_id = art.id and art.bool_delete_enum = 0 and pro.task_type_enum = 2 left join tech_assemble ass on pro.product_id = ass.id and ass.bool_delete_enum = 0 and pro.task_type_enum = 16 left join mes_building_team_user_link tulink on pro.team_id = tulink.team_id and tulink.bool_delete_enum = 0 and tulink.bool_leader_enum = 1
pro.bool_delete_enum = 0 and pro.quantity > pro.inspection_quantity
and
pro.team_id in
#{team.id}
and (art.structure_class_id in
#{classId}
or ass.assemble_config_id in
#{classId}
)
and DATE_FORMAT(pro.create_time, '%Y-%m-%d %H') >= DATE_FORMAT(#{startDate}, '%Y-%m-%d %H')
and DATE_FORMAT(pro.create_time, '%Y-%m-%d %H') <= DATE_FORMAT(#{endDate}, '%Y-%m-%d %H')
and task.project_id in
#{item}
and shop.id = #{workShopId}

SELECT line.id production_line_id, cp.short_name, ord.order_number, line.NAME production_line_name, ROUND(SUM(pro.task_quantity * art.net_weight)/1000,2) AS totalWeight, IFNULL(ROUND(SUM(CASE WHEN p.name = '焊接' THEN pro.complete_quantity ELSE 0 END) / SUM(CASE WHEN p.name = '焊接' THEN pro.task_quantity ELSE 0 END) * 100, 2),0) AS welding_rate, IFNULL(ROUND(SUM(CASE WHEN p.name = '制造' THEN pro.complete_quantity ELSE 0 END) / SUM(CASE WHEN p.name = '制造' THEN pro.task_quantity ELSE 0 END) * 100, 2),0) AS manufacture_rate, IFNULL(ROUND(SUM(CASE WHEN p.name = '装配' THEN pro.complete_quantity ELSE 0 END) / SUM(CASE WHEN p.name = '装配' THEN pro.task_quantity ELSE 0 END) * 100, 2),0) AS assembly_rate, IFNULL(ROUND(SUM(CASE WHEN p.name = '清磨' THEN pro.complete_quantity ELSE 0 END) / SUM(CASE WHEN p.name = '清磨' THEN pro.task_quantity ELSE 0 END) * 100, 2),0) AS spark_out_rate, IFNULL(ROUND(SUM(CASE WHEN p.name = '涂装' THEN pro.complete_quantity ELSE 0 END) / SUM(CASE WHEN p.name = '涂装' THEN pro.task_quantity ELSE 0 END) * 100, 2),0) AS painting_rate FROM mes_building_task_process pro LEFT JOIN contract_project cp ON pro.project_id = cp.id AND cp.bool_delete_enum = 0 LEFT JOIN mes_building_task_order ord ON pro.task_order_id = ord.id AND ord.bool_delete_enum = 0 LEFT JOIN tech_artifact art ON pro.product_id = art.id AND art.bool_delete_enum = 0 LEFT JOIN mes_building_process p ON pro.process_id = p.id AND p.bool_delete_enum = 0 LEFT JOIN mes_building_production_line line ON line.id = pro.production_line_id AND line.bool_delete_enum = 0 WHERE pro.bool_delete_enum = 0 AND pro.task_type_enum = 2 AND p.name IN ('焊接', '制造', '装配', '涂装','清磨') and line.bool_enabled_enum = 1
and YEAR(pro.create_time) = #{year}
and pro.workshop_id = #{workShopId}
and pro.production_line_id = #{productionId}
GROUP BY cp.short_name, ord.order_number, line.id;

SELECT cp.id projectId, cp.short_name projectName, ROUND((IFNULL(SUM(case when p.name = '下料' then pro.complete_quantity else 0 end),0) / IFNULL(SUM(case when p.name = '下料' then pro.task_quantity else 0 end),0) * 100),2) blankingRate, ROUND((IFNULL(SUM(case when p.name = '组立' then pro.complete_quantity else 0 end),0) / IFNULL(SUM(case when p.name = '组立' then pro.task_quantity else 0 end),0) * 100),2) assembleRate, ROUND((IFNULL(SUM(case when p.name = '门焊' then pro.complete_quantity else 0 end),0) / IFNULL(SUM(case when p.name = '门焊' then pro.task_quantity else 0 end),0) * 100),2) buriedArcRate, ROUND((IFNULL(SUM(case when p.name = '装配' then pro.complete_quantity else 0 end),0) / IFNULL(SUM(case when p.name = '装配' then pro.task_quantity else 0 end),0) * 100),2) assemblyRate, ROUND((IFNULL(SUM(case when p.name = '焊接' then pro.complete_quantity else 0 end),0) / IFNULL(SUM(case when p.name = '焊接' then pro.task_quantity else 0 end),0) * 100),2) solderingRate, ROUND((IFNULL(SUM(case when p.name = '清磨' then pro.complete_quantity else 0 end),0) / IFNULL(SUM(case when p.name = '清磨' then pro.task_quantity else 0 end),0) * 100),2) grindingRate, ROUND((IFNULL(SUM(case when p.name = '涂装' then pro.complete_quantity else 0 end),0) / IFNULL(SUM(case when p.name = '涂装' then pro.task_quantity else 0 end),0) * 100),2) liveryRate, ROUND((IFNULL(SUM(case when p.name = '制造' then pro.complete_quantity else 0 end),0) / IFNULL(SUM(case when p.name = '制造' then pro.task_quantity else 0 end),0) * 100),2) manufactureRate FROM mes_building_task_process pro LEFT JOIN contract_project cp ON pro.project_id = cp.id AND cp.bool_delete_enum = 0 LEFT JOIN tech_artifact art ON pro.product_id = art.id AND art.bool_delete_enum = 0 LEFT JOIN mes_building_process p ON pro.process_id = p.id AND p.bool_delete_enum = 0 WHERE pro.bool_delete_enum = 0
and YEAR(pro.create_time) = #{year}
and pro.workshop_id = #{workShopId}
and pro.production_line_id = #{productionId}
GROUP BY cp.id

SELECT process.NAME AS processName, a.id AS teskProcessId, w.NAME AS workshopName, l.user_name AS teamName, a.project_id, task_order.order_number, CASE a.sequence WHEN 0 THEN sum( a.task_quantity - a.inspection_quantity ) ELSE sum( a.need_quantity - a.inspection_quantity ) END un_quantity FROM mes_building_task_process a INNER JOIN mes_building_workshop w ON w.id = a.workshop_id AND w.bool_delete_enum = 0 INNER JOIN mes_building_groups_team_link groups_team_link ON a.groups_id = groups_team_link.groups_id AND groups_team_link.bool_delete_enum = 0 INNER JOIN mes_building_team_user_link l ON l.team_id = groups_team_link.team_id AND l.bool_delete_enum = 0 AND l.bool_leader_enum = TRUE INNER JOIN mes_building_process process ON process.id = a.process_id AND process.bool_delete_enum = 0 INNER JOIN mes_building_task_order task_order ON a.task_order_id = task_order.id AND task_order.bool_delete_enum = 0 INNER JOIN contract_project cp ON a.project_id = cp.id AND cp.bool_delete_enum = 0 WHERE a.bool_delete_enum = 0 and a.task_quantity > a.inspection_quantity and need_quantity > 0
AND a.ask_complete_time < #{crrentTime}
GROUP BY processName, workshopName, teamName, teskProcessId, a.project_id, task_order.order_number;

SELECT
taskProcess.id AS taskProcessId,
taskProcess.task_id,
taskProcess.process_id,
taskProcess.team_id,
artifact.structure_class_id AS classId,
taskProcess.task_quantity,
taskProcess.inspection_quantity
FROM
mes_building_task_process taskProcess
LEFT JOIN tech_artifact artifact  ON artifact.id  = taskProcess.product_id
AND artifact.bool_delete_enum = 0
WHERE taskProcess.bool_delete_enum = 0 and  taskProcess.tasK_type_enum = 2
and taskProcess.project_id = #{projectId}

    AND taskProcess.monomer_id = #{monomerId}


    AND taskProcess.workshop_id = #{workshopId}


    AND taskProcess.production_line_id = #{productionLineId}


    AND artifact.structure_class_id = #{classId}


    AND artifact.serial_number  LIKE CONCAT('%',#{productSerialNumber},'%')


    and taskProcess.area_id in
    
        #{areaId}
    


    and taskProcess.product_id in
    
        #{artifactId}
    


    and taskProcess.area_batch_id in
    
        #{areaBatchId}

SELECT #{processId} AS processId, 7 AS lossWorkProgressStatisticsEnum, #{taskTypeEnum} AS taskTypeEnum, ym_t.`year_month`, ROUND(mbcl_t.productMonthOutput,3) AS productMonthOutput FROM (
select DATE_FORMAT(#{i}, '%Y-%m') as `year_month`
) ym_t LEFT JOIN ( SELECT DATE_FORMAT( mbcl.create_time, '%Y-%m' ) AS `year_month`, SUM(mbcl.task_quantity * ifnull(product.net_weight,0)) / 1000 AS productMonthOutput FROM mes_building_task_process mbcl
LEFT JOIN tech_machine_part product on product.id = mbcl.product_id and product.bool_delete_enum = 0
LEFT JOIN tech_artifact product on product.id = mbcl.product_id and product.bool_delete_enum = 0
LEFT JOIN tech_assemble product on product.id = mbcl.product_id and product.bool_delete_enum = 0
WHERE mbcl.bool_delete_enum = 0
and mbcl.project_id = #{projectId}
and mbcl.workshop_id = #{workShopId}
and mbcl.process_id = #{processId} and mbcl.task_type_enum = #{taskTypeEnum}
AND date_format(mbcl.create_time, '%Y-%m') >= #{minYearMonth}
AND date_format(mbcl.create_time, '%Y-%m') <= #{maxYearMonth}
GROUP BY DATE_FORMAT( mbcl.create_time, '%Y-%m' ) ) mbcl_t ON ym_t.`year_month` = mbcl_t.`year_month`

SELECT #{processId} AS processId, 9 AS lossWorkProgressStatisticsEnum, #{taskTypeEnum} AS taskTypeEnum, ym_t.`year_month`, ROUND(mbcl_t.productMonthOutput,3) AS productMonthOutput FROM (
select DATE_FORMAT(#{i}, '%Y-%m') as `year_month`
) ym_t LEFT JOIN ( SELECT DATE_FORMAT( mbcl.create_time, '%Y-%m' ) AS `year_month`, SUM(mbcl.inspection_quantity * ifnull(product.net_weight,0)) / 1000 AS productMonthOutput FROM mes_building_produce_team_report mbcl
LEFT JOIN tech_machine_part product on product.id = mbcl.product_id and product.bool_delete_enum = 0
LEFT JOIN tech_artifact product on product.id = mbcl.product_id and product.bool_delete_enum = 0
LEFT JOIN tech_assemble product on product.id = mbcl.product_id and product.bool_delete_enum = 0
WHERE mbcl.bool_delete_enum = 0 and mbcl.inspection_quantity > 0
and mbcl.project_id = #{projectId}
and mbcl.workshop_id = #{workShopId}
and mbcl.process_id = #{processId} and mbcl.task_type_enum = #{taskTypeEnum}
AND date_format(mbcl.create_time, '%Y-%m') >= #{minYearMonth}
AND date_format(mbcl.create_time, '%Y-%m') <= #{maxYearMonth}
GROUP BY DATE_FORMAT( mbcl.create_time, '%Y-%m' ) ) mbcl_t ON ym_t.`year_month` = mbcl_t.`year_month`

SELECT #{processId} AS processId, 8 AS lossWorkProgressStatisticsEnum, #{taskTypeEnum} AS taskTypeEnum, ym_t.`year_month`, ROUND(mbcl_t.productMonthOutput,3) AS productMonthOutput FROM (
select DATE_FORMAT(#{i}, '%Y-%m') as `year_month`
) ym_t LEFT JOIN ( SELECT DATE_FORMAT( mbcl.create_time, '%Y-%m' ) AS `year_month`, SUM((mbcl.need_quantity - mbcl.inspection_quantity) * ifnull(product.net_weight,0)) / 1000 AS productMonthOutput FROM mes_building_task_process mbcl
LEFT JOIN tech_machine_part product on product.id = mbcl.product_id and product.bool_delete_enum = 0
LEFT JOIN tech_artifact product on product.id = mbcl.product_id and product.bool_delete_enum = 0
LEFT JOIN tech_assemble product on product.id = mbcl.product_id and product.bool_delete_enum = 0
WHERE mbcl.bool_delete_enum = 0 and mbcl.sequence != 0
and mbcl.project_id = #{projectId}
and mbcl.workshop_id = #{workShopId}
and mbcl.task_type_enum = #{taskTypeEnum} and mbcl.need_quantity > mbcl.inspection_quantity
and mbcl.process_id = #{processId}
AND date_format(mbcl.create_time, '%Y-%m') >= #{minYearMonth}
AND date_format(mbcl.create_time, '%Y-%m') <= #{maxYearMonth}
GROUP BY DATE_FORMAT( mbcl.create_time, '%Y-%m' ) ) mbcl_t ON ym_t.`year_month` = mbcl_t.`year_month`

select a.project_id projectId, a.workshop_id workShopId, d.branchCompanyIds branchCompanyIds, a.short_name projectName, a.serial_number serialNumber, a.process_id processId, a.process_name processName, a.task_type_enum taskTypeEnum, a.quantity quantity, round(a.weight,4) weight from( SELECT tp.project_id, tp.workshop_id, cp.serial_number, cp.short_name, pro.id process_id, pro.`name` process_name, tp.task_type_enum, CASE tp.task_type_enum WHEN 1 THEN sum(tp.need_quantity - tp.inspection_quantity) WHEN 16 THEN sum(tp.need_quantity - tp.inspection_quantity) WHEN 2 THEN sum(tp.need_quantity - tp.inspection_quantity) END quantity, CASE tp.task_type_enum WHEN 1 THEN sum((tp.need_quantity - tp.inspection_quantity) * part.net_weight) WHEN 16 THEN sum((tp.need_quantity - tp.inspection_quantity) * ass.net_weight) WHEN 2 THEN sum((tp.need_quantity - tp.inspection_quantity) * art.net_weight) END weight FROM mes_building_task_process tp LEFT JOIN contract_project cp ON tp.project_id = cp.id AND cp.bool_delete_enum = 0 LEFT JOIN mes_building_process pro ON tp.process_id = pro.id AND pro.bool_delete_enum = 0 LEFT JOIN tech_machine_part part ON tp.product_id = part.id AND part.bool_delete_enum = 0 AND tp.task_type_enum = 1 LEFT JOIN tech_assemble ass ON tp.product_id = ass.id AND ass.bool_delete_enum = 0 AND tp.task_type_enum = 16 LEFT JOIN tech_artifact art ON tp.product_id = art.id AND art.bool_delete_enum = 0 AND tp.task_type_enum = 2 WHERE tp.bool_delete_enum = 0 and tp.need_quantity > tp.inspection_quantity
and tp.workshop_id = #{workshopId}
and cp.short_name LIKE concat('%', #{projectSerialNumber}, '%') or cp.serial_number = #{projectSerialNumber}
GROUP BY tp.project_id, tp.workshop_id, cp.short_name, tp.process_id, pro.`name`, tp.task_type_enum )a left join (select project_id,group_concat(branch_company_id) branchCompanyIds from project_branch_company_link where bool_delete_enum = 0 group by project_id)d on a.project_id = d.project_id ORDER BY a.task_type_enum,a.process_id

SELECT ws.project_id projectId, ws.workshop_id workShopId, sum(ws.quantity) inboundQuantity, CASE ws.product_type WHEN 1 THEN sum(ws.quantity * part.net_weight) WHEN 16 THEN sum(ws.quantity * ass.net_weight) WHEN 2 THEN sum(ws.quantity *art.net_weight) END inboundWeight, sum(ws.cargo_quantity) cargoQuantity, CASE ws.product_type WHEN 1 THEN sum(ws.cargo_quantity * part.net_weight) WHEN 16 THEN sum(ws.cargo_quantity * ass.net_weight) WHEN 2 THEN sum(ws.cargo_quantity *art.net_weight) END cargoWeight FROM mes_building_warehouse_summary ws LEFT JOIN contract_project cp ON ws.project_id = cp.id AND cp.bool_delete_enum = 0 LEFT JOIN tech_machine_part part ON ws.product_id = part.id AND part.bool_delete_enum = 0 AND ws.product_type = 1 LEFT JOIN tech_assemble ass ON ws.product_id = ass.id AND ass.bool_delete_enum = 0 AND ws.product_type = 16 LEFT JOIN tech_artifact art ON ws.product_id = art.id AND art.bool_delete_enum = 0 AND ws.product_type = 2 WHERE ws.bool_delete_enum = 0 AND ws.product_type IN ( 1, 2, 16 )
and ws.workshop_id = #{workshopId}
and cp.short_name LIKE concat('%', #{projectSerialNumber}, '%') or cp.serial_number = #{projectSerialNumber}
GROUP BY ws.project_id,ws.workshop_id,ws.product_type

select a.project_id projectId, a.workshop_id workShopId, a.short_name projectName, a.process_id processId, a.productId, a.process_name processName, a.serialNumber, a.specification, a.productName, a.task_type_enum taskTypeEnum, sum(a.quantity) quantity, a.net_weight, sum(a.total_weight) totalWeight from( SELECT tp.project_id, tp.workshop_id, CASE tp.task_type_enum WHEN 1 THEN part.id WHEN 16 THEN ass.id WHEN 2 THEN art.id END productId, cp.short_name, pro.id process_id, pro.`name` process_name, tp.task_type_enum, CASE tp.task_type_enum WHEN 1 THEN tp.need_quantity - tp.inspection_quantity WHEN 16 THEN tp.need_quantity - tp.inspection_quantity WHEN 2 THEN tp.need_quantity - tp.inspection_quantity END quantity, CASE tp.task_type_enum WHEN 1 THEN part.serial_number WHEN 16 THEN ass.serial_number WHEN 2 THEN art.serial_number END serialNumber, CASE tp.task_type_enum WHEN 1 THEN part.specification WHEN 16 THEN ass.specification WHEN 2 THEN art.specification END specification, CASE tp.task_type_enum WHEN 1 THEN part.name WHEN 16 THEN ass.name WHEN 2 THEN art.name END productName, CASE tp.task_type_enum WHEN 1 THEN part.net_weight WHEN 16 THEN ass.net_weight WHEN 2 THEN art.net_weight END net_weight, CASE tp.task_type_enum WHEN 1 THEN (tp.need_quantity - tp.inspection_quantity) * part.net_weight WHEN 16 THEN (tp.need_quantity - tp.inspection_quantity) * ass.net_weight WHEN 2 THEN (tp.need_quantity - tp.inspection_quantity) * art.net_weight END total_weight FROM mes_building_task_process tp LEFT JOIN contract_project cp ON tp.project_id = cp.id AND cp.bool_delete_enum = 0 LEFT JOIN mes_building_process pro ON tp.process_id = pro.id AND pro.bool_delete_enum = 0 LEFT JOIN tech_machine_part part ON tp.product_id = part.id AND part.bool_delete_enum = 0 AND tp.task_type_enum = 1 LEFT JOIN tech_assemble ass ON tp.product_id = ass.id AND ass.bool_delete_enum = 0 AND tp.task_type_enum = 16 LEFT JOIN tech_artifact art ON tp.product_id = art.id AND art.bool_delete_enum = 0 AND tp.task_type_enum = 2 WHERE tp.bool_delete_enum = 0 and tp.need_quantity > tp.inspection_quantity
and tp.project_id = #{projectId}
and tp.workshop_id = #{workshopId}
and tp.task_type_enum = #{taskTypeEnum}
and tp.process_id = #{processId}
and cp.short_name LIKE concat('%', #{projectSerialNumber}, '%') or cp.serial_number = #{projectSerialNumber}
)a group by a.project_id, a.workshop_id, a.short_name, a.process_id, a.productId, a.process_name, a.serialNumber, a.specification, a.productName, a.task_type_enum, a.net_weight

SELECT mbtp.*, project.id AS 'project.id', project.serial_number AS 'project.serialNumber', project.name AS 'project.name', project.short_name AS 'project.shortName', mbto.id AS 'taskOrder.id', mbto.order_number AS 'taskOrder.orderNumber', process.id AS 'process.id', process.name AS 'process.name', team.id AS 'team.id', team.name AS 'team.name' FROM mes_building_task_process mbtp LEFT JOIN contract_project project ON project.bool_delete_enum = 0 AND project.id = mbtp.project_id LEFT JOIN mes_building_task_order mbto ON mbto.bool_delete_enum = 0 AND mbto.id = mbtp.task_order_id LEFT JOIN mes_building_process process ON process.bool_delete_enum = 0 AND process.id = mbtp.process_id LEFT JOIN ( SELECT mbt.id, mbtul.user_name AS name FROM mes_building_team mbt LEFT JOIN mes_building_team_user_link mbtul ON mbtul.bool_delete_enum = 0 AND mbtul.bool_leader_enum = 1 AND mbtul.team_id = mbt.id WHERE mbt.bool_delete_enum = 0 ) team ON team.id = mbtp.team_id WHERE mbtp.bool_delete_enum = 0
AND mbtp.project_id IN
#{item}
AND mbtp.workshop_id = #{workshopId}

SELECT '滞后信息' AS messageType, project.id AS projectId, project.name AS projectName, project.short_name AS projectShortName, project.serial_number AS projectSerialNumber, tastOrder.id AS taskOrderId, tastOrder.order_number AS taskOrderOrderNumber, process.id AS processId, process.name AS processName, t.ask_complete_date AS askCompleteDate, t.task_quantity AS taskQuantity, t.inspection_quantity AS inspectionQuantity FROM ( SELECT mbtp.project_id, mbtp.task_order_id, DATE(mbtp.ask_complete_time) AS ask_complete_date, mbtp.process_id, SUM(IFNULL(mbtp.task_quantity, 0)) AS task_quantity, SUM(IFNULL(mbtp.inspection_quantity, 0)) AS inspection_quantity FROM mes_building_task_process mbtp WHERE mbtp.bool_delete_enum = 0 AND mbtp.complete_time IS NULL AND DATE(ask_complete_time) < #{now}
AND mbtp.workshop_id = #{workshopId}
AND mbtp.project_id IN
#{item}
GROUP BY mbtp.project_id, mbtp.task_order_id, DATE(mbtp.ask_complete_time), mbtp.process_id ) t LEFT JOIN contract_project project ON t.project_id = project.id AND project.bool_delete_enum = 0 LEFT JOIN mes_building_task_order tastOrder ON t.task_order_id = tastOrder.id AND tastOrder.bool_delete_enum = 0 LEFT JOIN mes_building_process process ON t.process_id = process.id AND process.bool_delete_enum = 0
